window.FS_DATA=window.FS_DATA||{};FS_DATA["sinaksari_02"]={"month":2,"name":"Shkurt","days":[{"d":1,"m":2,"blocks":[{"t":"intro","x":"Më 1 të këtij muaji, nderojmë Vigjiljen e festës së Paraqitjes së Zotit tonë Jisu Krisht në Tempull."},{"t":"li","x":"Kujtimin e dëshmorit të madh Trifoni nga Lampsaka e Frigjisë, u martirizua para vitit 251."},{"t":"li","x":"Kujtimin e shenjtorëve Perpetua, Saturi, Revokati, Saturnini, Sekundi dhe Felisitata, të cilët u martirizuan në Kartagjenë të Afrikës në 202-203."},{"t":"li","x":"Kujtimin e dëshmorit Theon, të cilin e vranë me shpatë bashkë me dy djemtë e tij."},{"t":"li","x":"Kujtimin e martirit Karion, mbaroi pasi ia shqyen gjuhën."},{"t":"li","x":"Kujtimin e oshënarit Petro nga Galatia në shekullin e 4-t."},{"t":"li","x":"Kujtimin e oshënarit Venedimiani, asketizoi në Malin Shën Afksenti në Vithini të Azisë së Vogël, në shekullin e 5-6."},{"t":"li","x":"Kujtimin e oshënarit dhe rrëfyesit Timothe, fjeti në paqe."},{"t":"li","x":"Kujtimin e etërve të shenjtë Davidi, Simeoni dhe Gjergji në Mitilinë, të cilët i vranë me shigjeta, në shekullin e 8."},{"t":"li","x":"Kujtimin e atit tonë Vasil Konfesori, kryepiskop i Selanikut të Greqisë, shekulli i 9."},{"t":"li","x":"Kujtimin e shën Ilias së Ri, u martirizua në Damask."},{"t":"li","x":"Kujtimin e dëshmorit i ri Anastas pikturuesi nga Nafplio i Greqisë, fjeti në vitin 1655."},{"t":"li","x":"Kujtimin e shën Brizhidës së Kildarit, e cila fjeti në paqe më 524."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Trifoni, martir"},{"t":"p","x":"Pinjoll i të krishterëve, kulloste patat në atdheun e tij Lampsakë, në bregdetin aziatik të Elispondit të Azisë së Vogël."},{"t":"p","x":"Njëherë u drejtua në perandorinë e Romës Gordiani (238) për të shëruar bijën e tij të vetme, ashtu siç kishte paralajmëruar demoni që e torturonte."},{"t":"p","x":"Vërtet, shpendërritësi shtatëmbëdhjetëvjeçar, tashmë mrekullibërës, mbasi kreshmoi një javë duke u lutur, e nxori demonin që u shfaq si qen i zi. Kjo solli tek Krishti shumë vëzhgues të së gjithë skenës."},{"t":"p","x":"Më pas u kthye në vendin e tij me delegacion nderi, duke i dhënë paratë që i kishte dhuruar mbreti lëmoshë rrugës."},{"t":"p","x":"Në përndjekjen e perandor Dekiut (249–251) i njohuri për mrekullitë dhe aktivitetin e tij apostolik Trifoni (greqisht = i butë) u mor në pyetje në Nikea nga krahinari."},{"t":"p","x":"I patundur në shpresëtari, kaloi tortura të tmerrshme: varje dhe njëkohësisht goditje me shpatë, rrahje, tërheqje zvarrë i lidhur mbas kuajve në vende të ashpra, ecje me gozhdë të ngulura në këmbë, ndrydhje, djegie të brinjëve me llambadhe."},{"t":"p","x":"Por kishte dhe ngushëllim hyjnor. Panë një kurorë qiellore të zbresë mbi kokën e tij."},{"t":"p","x":"Së fundi, kur krahinari nuk kishte më shpresë, urdhëroi vdekjen nëpërmjet shpatës së atletit (dëshmorit). Por ai fjeti pak më përpara se t’i prisnin kokën, kur po që falej (250)."},{"t":"p","x":"Lipsanin e shenjtë, sipas porosisë së dëshmorit gjatë një vizioni, besimtarët e transportuan dhe e varrosën në atdheun e tij. Më vonë e shpunë në Konstandinopojë dhe më pas në Romë."},{"t":"p","x":"Për mrekullitë e tij mbas vdekjes, të cilat lidheshin me natyrën, shenjti nderohet si mbrojtës i bimësisë."},{"t":"h","x":"Petro në Galatia"},{"t":"p","x":"Jetëshkrimin e tij e bëri Theodhoriti, episkop i Kirit (qytet i Sirisë). Kur ishte i vogël Theodhoriti, shenjti e merrte në prehër dhe i jepte rrush për të ngrënë."},{"t":"p","x":"Origjina e tij ishte nga krahina e Ankarasë (Galatia në Azinë e Vogël). Që në moshën 7 vjeç u largua nga shtëpia dhe filloi ushtrimin deri në moshën 99 vjeç kur fjeti."},{"t":"p","x":"Pasi luftoi shpirtërisht në vendin e vet, bëri pelegrinazh në Vendet e Shenjta dhe pastaj u vendos në një varr në Antioki të Sirisë. Antiokia u bë atdheu i tij i dytë ngaqë njerëzit ishin perëndidashës."},{"t":"p","x":"Një herë në dy ditë hante pak bukë. Pranoi të marrë afër vetes një njeri të demonizuar, të cilin e kishte çliruar nga demonët."},{"t":"p","x":"Tek ai shkoi edhe e ëma e Theodhoritit së cilës i ishte dëmtuar syri. Ajo ishte e re, ekspozonte tej mase pamjen e saj të jashtme dhe stolisej me ar. E shëroi - siç kishte shëruar tashmë dhe një aristokrate - por më parë i tha:"},{"t":"p","x":"“Nëse një piktor i paaftë korrigjon gjoja, një vepër të një piktori të talentuar a nuk do të zemërohet ky i fundit? Perëndia, bija ime, indinjohet që ju lyheni, është njësoj sikur Ta akuzoni se nuk mund t’ju bëjë të bukura. Ju formon për interesin tuaj që të mos keni lavdidashje të rremë ose që të mos skandalizoni”... E reja u korrigjua përgjithmonë."},{"t":"p","x":"Çliroi një kuzhinier nga një demon, të cilin më parë e detyroi “të fliste” të pohonte ç’i kishte ngjarë:"},{"t":"p","x":"Ky kuzhinier, duke bërë shaka dhe duke u hequr si murg, çlironte gjoja shërbëtoret nga demonët. Ato kishin siguruar se murgjit nxorën demonët. Pra djalli i hyri kuzhinierit për të parë nëse ndonjë murg do të mund ta dëbonte. Dhe u bind faktikisht: E dëboi oshënari."},{"t":"p","x":"Një shërbëtore u arratis dhe u bë askete. Ndërkaq zotëria i saj - një gjeneral i dhënë pas femrave - e riktheu, por ai u verbua kur do t’i prishte virgjërinë. Ajo më pas u sëmur nga një kancer i dhimbshëm i gjirit. Lehtësohej vetëm kur thërriste dhe vinte shenjti, derisa vdiq."},{"t":"p","x":"Petro vizitoi gjithashtu dhe shëroi nënën e Theodhoritit, e cila sapo e kishte lindur dhe do të vdiste nga ethet e lehonisë."},{"t":"p","x":"Një herë tjetër preu në mes rripin e tij të gjerë, gjysmën e të cilit ua dha atyre. Kur sëmureshin ata vetë ose të tjerët, e vendosnin atë mbi vete dhe shëroheshin, derisa një i shëruar të cilit i kishin dhënë rripin, e mbajti përgjithmonë duke u treguar mosmirënjohës."},{"t":"p","x":"Petro shumë mrekullibërës nderohet edhe më 25 nëntor dhe quhet Hezikast."},{"t":"h","x":"Perpetua dhe ata që ishin me të, martirë"},{"t":"p","x":"Mbaruan më 202 në Kartagjenë, në bregdetin verior të Afrikës. Historia e tyre u shkrua pjesërisht nga Perpetua, nga katekisti i tyre Satiri dhe apologjeti e bashkëkohësi Tertuliani. U kapën si katikumenë. Vivia Perpetua (latinisht = e gjallë vazhdimisht), 22 vjeçe, vinte nga një fis aristokratësh në një qytet afrikan. Kishte një foshnjë nga burri i saj, nga i cili duket se ishte ndarë, sepse ishte idhujtar."},{"t":"p","x":"Saturnini (=Kronosi) ose Satornili dhe Sekundi (=i dyti) ishin të rinj në moshë ashtu si edhe skllevërit e Perpetusë, Refkati dhe Felicitata (=shumë e lumtur), me sa duket ishte e shoqja e Refkatit, e cila ishte shtatzënë. Grupit iu shtua edhe Satiri që t’i mbështeste. Katikumenët u pagëzuan në burg. Tri herë shkoi atje ati i Perpetuasë që ta bindte të kthehej në paganizëm. Lutej për hirin e foshnjës së saj, të pleqërisë së tij ose e kërcënonte..."},{"t":"p","x":"Shenjtorja dikur kishte pasur një vizion: një shkallë me thika dhe ganxha që shqyenin ata që ngjiteshin me plogështi, ndërsa poshtë priste rastin e volitshëm dragoi. Ajo u ngjit e ftuar nga katekisti dhe u gjend në kopshtin e mrekullueshëm (Parajsë), ku e mikpriti një plak gjigant i respektueshëm (Perëndia)! Ajo pa se e mundi dhe fitoi mbi djallin. Katekisti, ashtu si Perpetua, pa një vizion sikur të dy bashkë u futën në kopsht dhe aty takuan martirët e mëparshëm. Në burg Sekundi vdiq dhe Felicitata lindi, ndërsa gardiani u bë i krishterë falë sjelljes së të dënuarve. Martirët u ndeshën me gëzim me bishat. Perpetua nuk kishte lejuar që ta vishnin me rrobat priftërore pagane, siç ishte zakoni. Një ari dhe një leopard u sulën kundër burrave, një mështjerrë e egër kundër grave. Perpetua, në ekstazë, nuk i ndjeu goditjet e brirëve. Spektatorët në amfiteatër kishin kërkuar falje për gratë, por pastaj ndërruan mendje. Kështu të pestëve iu prenë kokat pasi u puthën me njëri-tjetrin."}]},{"d":2,"m":2,"blocks":[{"t":"intro","x":"Më 2 të këtij muaji, nderojmë Paraqitjen e Zotit Krisht në Tempull, këtë ditë, Simeoni i drejtë e priti Jisuin në krahë."},{"t":"li","x":"Kujtimin e dëshmorit Agathodhori nga Tiana e Kapadhokisë."},{"t":"li","x":"Kujtimin e dëshmorit të ri Jordani nga Trapezunda e Azisë së Vogël, i cili u martirizua në Konstandinopojë në vitin 1650."},{"t":"li","x":"Kujtimin e dëshmorit të ri Gabrieli murg, mbaroi me shpatë në Konstandinopojë në vitin 1676."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Paraqitja e Zotit tonë Jisu Krisht në Tempull *B"},{"t":"p","x":"Kur u plotësuan 40 ditët e pastrimit të nënës sipas Ligjit të Moisiut (Levitiku 12.2-4), e Tërëshenjta dhe shën Josifi e çuan fëmijën Jisu në Jerusalem për ta paraqitur para Zotit, sepse “çdo djalë i parëlindur do të jetë thirrur shenjt për Zotin” dhe duke ofruar flijim, siç është thënë në Ligjin e Zotit, një qengj, ose një çift turtujsh ose dy pëllumbash të rinj për ata që ishin më të varfrit. Zoti i qiellit dhe i tokës, Ligjëvënësi i popullit të tij Izrael, ai që nuk erdhi të shkatërronte Ligjin, (Matth. 5.17), por si mori natyrën tonë të vdekshme e restauroi me ardhjen e tij në botë duke iu bindur Ligjit. Burimi i çdo pasurie dhe i çdo hiri, bëhet më i përuluri dhe më i varfri ndër ne. Ai i nënshtrohet Ligjit që na u dha, dhe ne njerëzve, që nuk pushojmë së mëkatuari, na tregon se përmes bindjes pajtohemi me Perëndinë."},{"t":"p","x":"Megjithëse ai vetë nuk kishte nevojë për pastrim, pasi iu nënshtrua rrethprerjes në mish ditën e tetë, priti në shpellën e Bethlehemit që të kalonin ditët derisa të paraqitej në Tempullin e Lavdisë së tij me trupin njerëzor që mori për ta bërë tempull të përsosur të hyjnisë së tij. Vetë ai, Perëndia i panxënë dhe i pakuptueshëm paraqitet në Tempull edhe me flijimin e të varfërve: pëllumba dhe turtuj, simbole të pastërtisë, të paqes dhe të pafajësisë që Shpëtimtari, Miku i njerëzve vjen të na sjellë. Kur arritën në Tempull, ata u pritën nga prifti i madh Zaharia, ati i shën Joan Pagëzorit, i cili në një mënyrë krejt të papritur e vendosi Hyjlindësen në vendin që u qe rezervuar virgjëreshave. Në atë çast mbërriti në Tempull një njeri me emrin Simeon. Njeri i drejtë, i perëndishëm dhe që zbatonte urdhërimet e Perëndisë. Ai kishte pritur prej kohësh përmbushjen e profecisë që Fryma e Shenjtë i kishte frymëzuar: d.m.th. se nuk do të vdiste para se të shikonte dhe prekur Krishtin Zot. Ky plak, i cili parafiguron tërë pritjen e Izraelit, shtriu krahët për të pritur Zotin si mbi një fron Keruvimesh, e bekoi Perëndinë dhe tha: Tani, lëre në paqe shërbëtorin tënd, o Zot, se sytë e mi panë shpëtimin tënd” (Lluk. 2.9)."},{"t":"p","x":"Ky plak, duke parë dhe prekur Shpëtimtarin që u lajmërua nga të drejtët dhe profetët që kohë më parë, mund t’i kërkonte Perëndisë me plot besim të ishte i çliruar nga lidhjet e mishit dhe të prishjes që t’i linte vend rinisë së përjetshme të Kishës. Solemnisht, ai shpallte shkatërrimin e figurave dhe shpallte profecinë e fundit që lidhet me Shpëtimtarin duke i parathënë Hyjlindëses se vuajtja dhe ngjallja jetëdhënëse do të jenë një shenjë për rënien e të pabesëve dhe ngritjen e atyre që besojnë tek ai. Atje ishte edhe një grua me emrin Ana, nga fisi i Aserit, e cila ishte e thyer në moshë dhe e njohur për ata që shkonin në Tempull, pas shtatë vjetësh martese, mbeti e ve, i shërbente vazhdimisht Perëndisë duke pritur ardhjen e Mesisë me kreshmë e lutje. Edhe ajo u afrua drejt fëmijës Jisu dhe filloi të lavdëronte Perëndinë duke shpallur tek të gjithë çlirimin e Izraelit."},{"t":"p","x":"Në përshkrimin që i bën Ungjillori Lluka, kjo ditë njihet ndryshe si “Takimi”, sepse Krishti takoi popullin e tij në prani të plakut Simeon dhe profeteshës Ana. Këta dy persona kishin vite që e prisnin Shpëtimtarin dhe tani e takuan atë. Menjëherë Simeoni thirri dhe tha: \"O Zot, tani lëre shërbëtorin tënd të largohet në paqe, sepse sytë e mi panë shpëtimin\"."},{"t":"p","x":"Le ta takojmë Krishtin dhe le ta marrim atë në shpirtrat tanë. Çdo shpirt duhet të jetë një tempull i Perëndisë, në të cilin Maria sjell Jisuin dhe secili prej nesh le ta marë ne krahet e tij si Simeoni dhe të thotë;\"Sytë e mi panë shpëtimin\"."},{"t":"p","x":"Lutja e Simeonit: \"Tani përlëshoje shërbëtorin tënd në paqe\" nuk kupton thjesht që dikush, i cili ka parë Krishtin dhe e ka mbajtur në krahët e tij, dhe tashmë mund të vdesë në paqe. Ajo nënkupton për ne që duke parë shpëtimtarin, jemi të çliruar nga mëkati."},{"t":"p","x":"Prandaj, edhe kur një foshnjë mbush dyzetë ditë, sillet në kishë për t’u bekuar dhe prifti lëçit lutjet për të dhe për nënën. Më pas ai e bekon foshnjën duke i bërë shenjën e kryqit e duke thënë: \"Kishërohet shërbëtori i Perëndisë (emri) në emrin e Atit, të Birit dhe të Shpirtit të Shenjtë\". Amin."},{"t":"p","x":"Nëse foshnja është djalë, prifti e merr atë brenda në altar. Pas bekimit të tretë, prifti thotë lutjen e Simeonit: \"O Zot, tani lëre shërbëtorin tënd të shkojë në paqe, sipas fjalës sate, se sytë e mi kanë parë shpëtimin që Ti ke përgatitur për popujt, dritën nëpërmjet të cilës do t’u zbulohesh paganëve dhe praninë tënde madhështore në popullin e Izraelit”."}]},{"d":3,"m":2,"blocks":[{"t":"intro","x":"Më 3 të këtij muaji, nderojmë Mbledhjen e Simeon Hyjpritësit edhe profeteshës Ana."},{"t":"li","x":"Kujtimin e profetit të izraelitëve Azaria."},{"t":"li","x":"Kujtimi e dëshmorëve Adriani dhe Euvuli, të cilët u martirizuan në Qesari para vitit 311."},{"t":"li","x":"Kujtimin e dëshmorit Vlashi, bari nga Qesaria."},{"t":"li","x":"Kujtimi e dëshmorëve Pavli dhe Simoni. Mbaruan me shpatë."},{"t":"li","x":"Kujtmi i oshënarit Klaudi."},{"t":"li","x":"Kujtimin e mbretit të Rusisë Romano Vladimiroviç në viti 1285."},{"t":"li","x":"Kujtimin e dëshmorëve të rinj Joani, Stamati vëllezër nga gjaku bashkë me Nikollën, kryetarin e anijës së tyre, të cilët u martirizuan në vitin 1822."},{"t":"li","x":"Kujtimin e atit tonë Nikolla, themelues i Kishës Orthodhokse në Japoni dhe kryepiskopi i parë në Tokio (1855-1912)."},{"t":"li","x":"Kujtimin e shën Simeoni, episkop i parë i Tverit."},{"t":"li","x":"Kujtimin e shën Romanit, princi i Ugliçit."},{"t":"li","x":"Kujtimin e shën Anskarit, episkop i Hamburgut dhe apostull i Skandinavisë, fjeti në paqe më 865."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona."},{"t":"h","x":"Amin."},{"t":"h","x":"Simeoni i drejtë dhe profetesha Ana"},{"t":"p","x":"Sipas Ungjillorit Lluka, Simeoni ishte nga Jerusalemi. Shquhej si njeri i drejtë, besimtar dhe i ndriçuar nga Shpirti i Shenjtë. Gjithashtu Shpirti i Shenjtë i kishte zbuluar atij se nuk do të vdiste pa parë Krishtin. Ky lajm i gëzuar e fuqizoi dhe e ngushëlloi deri në moshë të thyer. 40ditë pas lindjes së Krishtit, Shpirti i Shenjtë informoi se ajo të cilën Simeoni priste u realizua. Kështu, ai u nis për të shkuar në tempull, i mbushur me ngazëllim duke pritur të realizohej ai bekim për të cilin e kishte vlerësuar Perëndia. Pasi mori foshnjen në krahë tha: “Tani, o Zot, lëre shërbëtorin tënd të vdesë në paqe sipas fjalës tate, sepse sytë i mi e panë shpëtimin tënd që e përgatite përpara gjithë popujve, dritën për të ndriçuar kombet”. Nuk kaloi shumë kohë dhe Simeoni dorëzoi në paqe shpirtin e tij tek Perëndia. Falënderimi dhe lavdërimi i tij drejtuar Perëndisë mbetet i pavdekshëm dhe jeton në mënyrë emocionuese në mbrëmësoren e kishës. Përshëndetja e Simeonit ishte në një farë mënyre nga ana e tij përfaqësim i gjithë burrave të shenjtë besimtarë, të cilët jetuan para Krishtit me shpresën e ardhjes së Shpëtimtarit Jisu Krisht."},{"t":"p","x":"Priftëresha Ana ishte nga fisi Asir, djali i tretë i Jakovit, dhe e bijë e Fanuelit. Mbeti e ve pas 7-vjetësh martesë. Më pas ajo gjeti ngushëllimin e saj tek lutja, kreshma, lëmosha dhe studimi i Shpirtit të Shenjtë. Për këtë vullnet të saj, Shpirti i Shenjtë jo vetëm që e ndihmoi në rrugën e besimit dhe të virtytit, por edhe i dha aftësi të profetizojë. U vlerësua të shikojë foshnjën e sapolindur të Virgjëreshës Mari dhe duke falënderuar Perëndinë predikoi kudo duke thënë se erdhi Mesia e shumëpritur. Ndërroi jetë në paqe në moshë shumë të thyer."},{"t":"h","x":"Nikolla i Japonisë"},{"t":"p","x":"Është themeluesi i Orthodhoksisë në Japoni, i cili u shpall shenjtor më 1970."},{"t":"p","x":"Joan Kasatkin, i biri i dhjakut Dhimitër, lindi më 22.8.1836 në Smolensk, provincë në perëndim të Moskës. Në moshën pesëvjeçare mbeti jetim nga nëna."},{"t":"p","x":"Në vitin e katërt të Akademisë Kishtare të Petropolit, u votua nga Sinodi i Shenjtë prift i konsullatës së Hakodatit, në veri të Japonisë. Shkoi atje më 1861, sapo u dorëzua hieromonak Nikolla, por filloi të predikojë mbas plot shtatë vjetësh të mësimit të gjuhës. Kishte dhe vështirësi të ambientit."},{"t":"p","x":"Fillimisht i vetëm në përpjekjen e mundimshme, në vitin 1865 bëri dy bashkëpunëtorë të çmuar vendas."},{"t":"p","x":"Më 1871, kur ishin 15 besimtarë, duke u kthyer nga udhëtimi në Rusi, sistemoi me miratim sinodi, misionarizmin dhe transferoi selinë në Tokio. Më 1874 misionarizmi përmblidhte nëntëqind besimtarë, mbasi ishte shpallur ligjërisht dekreti i vitit 1873, i cili u lejonte japonezëve Krishterimin, që doli në legalitet."},{"t":"p","x":"Më 1878 u organizua Kisha Orthodhokse, ku ishin 6 priftërinj, 27 katekistë dhe 51 ndihmës të tyre vendas."},{"t":"p","x":"Më 1885 Nikolla u bë kryebari i Kishës së Japonisë, e cila pak kohë më parë ishte ngritur në rang episkopate."},{"t":"p","x":"Mbas një pesëvjeçari u përurua në Tokio një kishë bizantine, e cila të paktën deri më 1961, ishte ndërtimi më i shkëlqyer i krishterë, i vendit."},{"t":"p","x":"Kryeprifti asket u kujdes, me gjithë mungesën e të ardhurave, të organizojë arsimin. Hapi shkolla, kryesisht katekiste, midis të cilave, një për gra dhe një për psaltë, ndërsa më 1878 hapi seminarin theologjik gjashtëvjeçar. Botoi dhe tre periodikë."},{"t":"p","x":"Një punë vigane kanë qenë përkthimet e Shkrimit të Shenjtë, librave liturgjikë, të Etërve, Kanuneve, Sinaksarëve etj. Që nga viti 1900, edhe vendasit autoktonë, shkruanin tashmë libra teologjikë."},{"t":"p","x":"Në luftën ruso-japoneze të vitit 1904 nuk iku, por duke qëndruar “në atdheun e vërtetë, Kishën”, e nxiste grigjën e tij për të kryer detyrën kombëtare dhe të lutet për fitoren."},{"t":"p","x":"Fjeti më 3.2.1912, ndërkohë që lulëzonin 266 bashkësi me 33.000 orthodhoksë."},{"t":"h","x":"Stamati, Joani, Nikolla, neomartirë"},{"t":"p","x":"U ushtruan (martirizuan) më 1822. Stamati dhe Joani, përkatësisht 18 dhe 22 vjeç ishin nga Speces, ishull në jug të Atikës (që banohet kryesisht nga arvanitas), fëmijë të Theodhor Gjinit dhe Anezës."},{"t":"p","x":"Dikur, siç po lundronin së bashku me pesë të tjerë për punë tregtie, erëra të fuqishme e degdisën anijen e tyre në Çemë (Krinë), në bregun perëndimor të Turqisë."},{"t":"p","x":"Të frikësuar, sepse agarinët ishin të egërsuar nga revolucioni grek i vitit 1821, takuan një të krishterë dhe i dhanë para që t’u sillte çfarë u nevojitej për riparimin e anijes së tyre. Por, ai solli turqit! Ata vranë dy nga detarët e sprovuar nëpër stuhi, që tentuan të iknin, kapën vëllezërit dhe kapitenin plak, Nikollën. Të tjerët u arratisën me not."},{"t":"p","x":"Më 26 janar robërit i shpunë tek pashai i ishullit Hios, që ndodhet përballë. Pashai urdhëroi dhe i prenë kokën Nikollës, i cili i qetë dhe i palëkundur nuk pranonte të konvertohej."},{"t":"p","x":"Sundimtari u premtoi shpërblim dy vartësve të tij, në qoftë se ata do të arrinin t’i shkëpusnin të dy të burgosurit nga Krishti. Për një javë rresht ata u përpoqën t’i joshnin të dy të rinjtë me dhurata apo t’i trembnin me ndëshkime, por më kot. Pashai i bezdisur, tha se më lehtë pritet koka e kaurit, sesa këmbëngulja kokëfortë e tij."},{"t":"p","x":"Të rinjtë paranjohën me zbulim fundin e tyre dhe ua bënë të ditur edhe të burgosurve që ishin bashkë me ta. Gjithashtu, i dërguan një rrëfim të shkruar episkopit të Hiosit dhe kërkuan Falënderimin Hyjnor, të cilin arriti t’ua dërgojë me një grua. U kunguan mbasi u lutën pothuaj gjithë natën."},{"t":"p","x":"Në mëngjes çdo gjë që kishin e dhanë lëmoshë, para se t’i dënonin, meqenëse shpallën se pranonin të copëtohen ende për hir të besimit të tyre. Joani për një çast u frikësua nga shpatat e zhveshura enkas, por e mbështeti Stamati (greqisht = ndalues), saqë së bashku deklaronin se po vdisnin për Jisuin. Kështu, i therën në afërsi të thertores së Hiosit."},{"t":"p","x":"Pas tri ditësh trupat e pavarrosur i hodhën në det, por deti i nxori diku në breg, përveç kokës së Joanit. Ato i mblodhi një i krishterë, i cili enkas mbikëqyrte atë pjesë të bregut ku punonte si regjës lëkurësh."}]},{"d":4,"m":2,"blocks":[{"t":"intro","x":"Më 4 të këtij muaji, nderojmë kujtimin e shën Isidor pilusiotit nga Mali i Pilusit nga Egjipti (360-440)."},{"t":"li","x":"Kujtimin e oshënarit Nikolla Studiti, nxënës i oshënar Theodhor Studitit, igumen në manastirin e tij dhe pohues i ikonave (793-868)."},{"t":"li","x":"Kujtimin e dëshmorit Avrami, episkop i Arvilit të Persisë 344."},{"t":"li","x":"Kujtimin e shën Nikita në Pitia."},{"t":"li","x":"Kujtimin e martirëve të shenjtë Filia, episkop i Tmuisit si dhe Filoromit."},{"t":"li","x":"Kujtimin e oshënarit Joan, episkop në Irinupolis, i cili mori pjesë në Sinodin e Parë në Nikea në vitin 325."},{"t":"li","x":"Kujtimin e oshënarit Jasim çudibërësit."},{"t":"li","x":"Kujtimin e dëshmorit Theoktisti, mbaroi me shpatë."},{"t":"li","x":"Kujtimin e oshënarit Nikita në Bizant."},{"t":"li","x":"Kujtimi të oshënarëve Avraami dhe Kopri nga Manastiri i Shpërfytyrimit të Shpëtimtarit tonë në Vologda të Rusisë në shekullin e 15."},{"t":"li","x":"Kujtimin e oshënarit Kiril çudibërësit nga Novgorodi i Rusisë 1532."},{"t":"li","x":"Kujtimin e dëshmorit të ri Josifi në Alepo, mbaroi me shpatë më 1686."},{"t":"li","x":"Kujtimin e shën Gjergjit, princ i Vladimirit."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Isidor pilusioti"},{"t":"p","x":"Ka lindur me sa duket në Aleksandri, rreth vitit 370 nga prindër të shquar dhe të virtytshëm. Pasi u shkollua thellësisht e mori përsipër barrën e lehtë të Zotit, d.m.th. u mobilizua në një manastir, në Kodrën e Pilusit, në degën perëndimore të Nilit, ndaj dhe quhet pilusioti. Prift dhe prijës, shembull morali dhe urtësie murgërore, fitoi një famë mbarorthodhokse. Punoi për disiplinën e murgjve dhe besnikëve."},{"t":"p","x":"Ruhen 1997 letra të tij - shkroi mijëra letra, pasi njerëz të shtresave të ndryshme kërkonin nëpërmjet letrave që i dërgonin atij zgjidhjen e problemeve të ndryshme të tyre. Letrat janë shkruar shkurt, por dinjitoze nga ana e stilit, ato dëshmojnë për frymëzim të perëndishëm dhe merreshin me dogmat, shpjegimin e Biblës dhe jetën shpirtërore."},{"t":"p","x":"Konsideronin lutjen, virtytin dhe besimin si gjëra të domosdoshme për shpëtimin; e shihnin monakizmin si mishërimin e përsosmërisë së krishterë; luftojnë kundër Arianizmit dhe Nestorianizmit; për më tepër, na ofrojnë rastësisht edhe informacionin e vlefshëm historik. Për të gjitha këto, kanë një rëndësi shumëdimesionale. Gjithashtu hartoi dhe dy dispensa që humbën."},{"t":"p","x":"Ishte mbrojtës i fuqishëm i kujtimit të shën Joan Gojartit (13 nëntor). Pra, arriti dhe bindi të afërmin e tij, shën Kirilin e Aleksandrisë (18 janar) që emri i tij të regjistrohej përsëri në diptikët e Kishës së Aleksandrisë. Më parë kishte një konflikt."},{"t":"p","x":"Në përgjithësi ka luajtur një rol të rëndësishëm në ndodhi-të kishtare në kohën e tij, madje kishte korrespondencë dhe këshillonte perandorin. Fjeti në paqe midis viteve 435 - 449."},{"t":"p","x":"Isidor, greqisht = i barabartë me dhuratë."},{"t":"h","x":"Theofil Pendimtari"},{"t":"p","x":"Megjithëse ishte lindor, nderohet si shenjtor tepër i njohur në Perëndim, ku e kujtojnë në data të ndryshme, si edhe më 14 tetor. Në Lindje nuk ka qenë shumë i njohur. Tregojnë se jeta e tij tërheqëse, frymëzoi Gëten rreth personazhit të Faustit. Biografinë e tij e shkroi një bashkëpunëtor i tij."},{"t":"p","x":"Ishte klerik me ofiqin e ikonomit, në Adhanë në juglindje të Azisë së Vogël (shek. e 6-të dhe 7-të)."},{"t":"p","x":"Kur episkopi i tyre ndërroi jetë, nuk e pranoi propozimin e të gjithëve që t’i zinte vendin, dhe u zgjodh një tjetër."},{"t":"p","x":"Më pas u ndodh në kushte jo të favorshme, e humbi titullin dhe po varfërohej. Të dhënat e reja i ndezin urrejtjen kundër eprorit të tij, dhe tashmë aspiron me zjarr gradën që e refuzoi në fillim."},{"t":"p","x":"I verbuar prej pasionit nuk ndalet përpara asgjëje! Shkon tek një magjistar hebre, i cili e lidh me djallin që i premton se do ta bëjë episkop, mjaft që ai të mohojë me shkrim Krishtin dhe të Tërëshenjtën…"},{"t":"p","x":"I mjeri nënshkruan, por pendohet menjëherë dhe kërkon në agoni ndreqjen e rënies tragjike."},{"t":"p","x":"Mbyllet në kishën e së Tërëshenjtës së Adhanës, vajton me lot të hidhur, godet gjoksin me grusht, kreshmon në mënyrë hiperbolike dhe kërkon falje për krimin."},{"t":"p","x":"Mbas dyzet ditësh sheh të Tërëshenjtën me pamje të ashpër. Ndërkohë i shfaqet përsëri pas tri ditësh dhe e fal. Më vonë i jep në gjumë kontratën diabolike, të cilën sapo zgjohet e gjen mbi kraharorin e tij!"},{"t":"p","x":"I mbushur me mirënjohje shkon në kishë dhe përpara gjithë besimtarëve i kërkon të falur episkopit, pasi i tregon të gjitha sa kishin ndodhur. Pajtohen dhe oshënarit i jepet përsëri grada."},{"t":"p","x":"Mbas pak ditësh, ndërsa lavdëronte pa pushuar Zonjën Hyjlindëse, u sëmur dhe fjeti, pasi më përpara ishte pranuar në misteret (kungata etj.) dhe kishte ndarë tek të vobektët të gjitha sa kishte."},{"t":"p","x":"Marrëveshje me demonin kishte nënshkruar dhe një i dashuruar i pashpresë – variantin më të afërt në lidhje me historinë e Faustit - të cilin shpëtoi Vasili i Madh (1 janar)."},{"t":"p","x":"Theofil, greqisht = Perëndia [është] mik [i tij]."}]},{"d":5,"m":2,"blocks":[{"t":"intro","x":"Më 5 të këtij muaji, nderojmë kujtimin e shën Agathisë, e cila u martirizua në vitin 251 në ishullin e Siçilisë."},{"t":"li","x":"Kujtimin e atit tonë Poliefkti, kryepiskop i Konstandinopojës (956-970)."},{"t":"li","x":"Kujtimin e oshënarit Theodhos i Skopelos në Kiliki."},{"t":"li","x":"Kujtimin e oshënarit Theodhosi, igumen në Manastirin Eleç në Ukrainë dhe më pas kryepiskop në Çernigov të Rusisë (1692-1696)."},{"t":"li","x":"Kujtimin e dëshmorit të ri Andoni i Athinës, i cili u martirizua në Konstandinopojë në vitin 1774."},{"t":"li","x":"Kujtimin e shën Avitit, episkop i Vjenës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Agathia, martire"},{"t":"p","x":"Për arsye të sojit të saj prej arkondi, pasurisë, bukurisë dhe karakterit shkëlqente në atdheun e saj, në Katania të Sicilisë."},{"t":"p","x":"Pas vdekjes, siç duket, të prindërve të saj idhujtarë, kur ishte 15 vjeçe, u arrestua në kohë të Dekës (249-251), nga sundimtari i shthurur, që vinte nga një fis jo shumë i njohur në Sicili. Ai kishte si qëllim ta shkëpuste nga Krishti e ta merrte për grua dhe kështu të shijonte gjithë të mirat e saj."},{"t":"p","x":"Përpjekjet e tij për ta bërë për vete, duke i bërë shumë lajka e premtime dështuan. Vajza e kundërshtoi, prandaj e dorëzoi tek një grua e përdalë. Për një muaj rresht e torturonte ose e joshte, por nuk arriti ta thyente rezistencën e saj."},{"t":"p","x":"Atëherë sundimtari urdhëroi dhe e mbyllën në burg, ku e reja shkoi me dëshirë. Ditën tjetër e varën, e digjnin dhe e kamxhikonin pa mëshirë. Pastaj i prenë gjinjtë, por në mesnatë në burg erdhi brenda një ndriçim i mbinatyrshëm, apostulli Petro (29 qershor) dhe e shëroi."},{"t":"p","x":"Të nesërmen, meqenëse martirja vazhdonte të mos pranonte t’u sakrifikonte perëndive, e tërhoqën zvarrë mbi copa tullash të mprehta dhe gjemba hekuri dhe më pas e hodhën në zjarr. Kur po lutej, një tërmet shkatërrues frikësoi bashkëqytetarët e saj, të cilët mësynë në ndërtesën qeveritare dhe këmbëngulën që të ndalojnë torturat! E çuan përsëri në burg, ku duke u lutur dorëzoi vërtet frymën."},{"t":"p","x":"E varrosi populli dhe engjëlli vendosi pllakën e varrit, ndërsa kuaj të tërbuar i shkaktuan tiranit vdekje të tmerrshme…"},{"t":"p","x":"Një vit më vonë vullkani i Etnës, që ndodhet shumë afër Katanias, shpërtheu dhe lumi i zjarrtë mbërriti në qytet (251). Njerëzit vrapuan, morën mbulesën e varrit të shenjtores, bënë litani dhe llava ndaloi!"},{"t":"p","x":"Romano-katolikët e nderojnë si mbrojtëse të Siçilisë dhe Maltës. Agathi, greqisht = e mirë."}]},{"d":6,"m":2,"blocks":[{"t":"intro","x":"Më 6 të këtij muaji, nderojmë kujtimin e atit tonë Foti i parë, patriark i Konstandinopojës në vitin 858-867 dhe 877-886."},{"t":"li","x":"Kujtimin e shën Vukolit të Smirnës, nxënës i shën Joan Theologut, shekulli i parë."},{"t":"li","x":"Kujtimin e dëshmores grua Fausta, bashkë me ata që besuan prej saj: Evilasi dhe Maksimi, u martirizuan në Kizikë të Azisë së Vogël para vitit 305."},{"t":"li","x":"Kujtimin e martirëve të shenjtë Dhorothea dhe Theofili."},{"t":"li","x":"Kujtimin e shën Faustit dhe Basilit, të cilët nderohen në Darion të Konstandinopojës."},{"t":"li","x":"Kujtimin e Jakov asketit nga Siria."},{"t":"li","x":"Kujtimin e oshënarëve Joan profeti dhe Varsanufi, të cilët jetuan në Manastirin e ava Seridos në Gaza të Palestinit në shekullin e 6."},{"t":"li","x":"Kujtimin e shën Dhorotheas së Kashinit."},{"t":"li","x":"Kujtimin e shën Vedastit, episkop i Arrasit."},{"t":"li","x":"Kujtimin e shën Amadit, episkop i Mastrihtit"},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Foti i Madh"},{"t":"p","x":"Figurë dominuese e Kishës dhe e letrave."},{"t":"p","x":"U lind rreth vitit 820 në Konstandinopojë, nga një familje e ngritur dhe e martirizuar nga kundërshtarët e ikonave. I ati ishte konfesori, shën Sergji (13 maj), i cili ishte vëllai i patrikut të Konstandinopojës, shën Tarasit (25 shkurt)."},{"t":"p","x":"I pajisur me aftësi natyrore të paarritshme, shumë shpejt u bë filozof, poet, orator, mjek, matematicien. Ai krijoi një bibliotekë private të rrallë."},{"t":"p","x":"U ngjit në postet më të larta politike, por ai dëshironte jetën asketike. Pas shkarkimit antikanonik (sipas të tjerëve ishte dorë-heqje) të patrikut shën Ignatit (23 tetor), Foti, pas presioneve të paimagjinueshme nga pallati mbretëror, tërhiqet: Për pesë ditë kalon të gjitha shkallët e hierarkisë kishtare dhe në Krishtilindjet e vitit 858 dorëzohet patrik i Konstandinopojës."},{"t":"p","x":"Këtej e tutje jeta e tij bëhet tejet e trazuar dhe shkruan në mënyrë të pashlyeshme historinë: Dënohet nga sinodi i Romës (863) që ndërhyn në çështjet e brendshme të Lindjes. Përsëri gjatë vitit 867 ai dënon në sinod perëndimorët për bastardimet e dogmave (fillimi i Skizmës së Romanokatolikëve). Në të njëjtin vit pasojnë internimi i tij nga perandori i ri, Vasil I (867-886) dhe rivendosja e Ignatit, që në mënyrë mallëngjyese i kërkojnë falje njëri-tjetrit në vitin 876."},{"t":"p","x":"Pas vdekjes së këtij të fundit (878), ai ribëhet patrik dhe rehabilitohet nga sinodi mbarëkristian (879-880). Por, përsëri internohet nga pallati mbretëror në një manastir (886), ku mbyllet jeta e tij dinamike mbi tokë (6 shkurt 891). Duhet shtuar se, në kuadrin e përpjekjes së tij të pasur hierapostolike, ai ndikoi në civilizimin e sllavëve dhe në veçanti të bullgarëve."},{"t":"p","x":"Ai ka lënë shumë shkrime teologjike dhe joteologjike: poetike, homeli, dogmatike, shpjeguese, këshilluese dhe dy vepra të njohura: Sinagogë Fjalësh dhe Biblioteka ose Mijëlibërshi, që merret edhe me veprat e lashta të humbura, prandaj është e çmuar."},{"t":"p","x":"Foti, greqisht = i ndritur."}]},{"d":7,"m":2,"blocks":[{"t":"intro","x":"Më 7 të këtij muaji, nderojmë kujtimin e oshënar Parthenit, episkop në Lampsakë të Azisë së Vogël në shekullin e 4."},{"t":"li","x":"Kujtimin e 1003 dëshmorëve bashkë me 4 rojet e mbretit të Romes, u martirizuan në Nikomedi të Azisë së Vogël mes viteve 285-305."},{"t":"li","x":"Kujtimin e shën Afdaktit dhe i gjashtë dëshmorëve nga Frigjia, të cilët mbaruan në zjarr."},{"t":"li","x":"Kujtimin e dëshmorit Theopempti bashkë me shokët e tij, mbaruan me shpatë."},{"t":"li","x":"Kujtimi e shën Aprioni, episkop në Qipro."},{"t":"li","x":"Kujtimin e oshënarit Petro nga Monovata."},{"t":"li","x":"Kujtimin e oshënarit të madh Llukai i Ri, themelues i Manastirit që mban emrin e tij në Vioti të Greqisë (896-953)."},{"t":"li","x":"Kujtimin e dëshmorit të ri Gjergji nga Kreta e Greqisë, i cili u martirizua në vitin 1867."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Partheni i Lampsakës"},{"t":"p","x":"Veproi gjatë shekullit të 4-t. I biri i dhjakon Kristoforit (ose Kristodhulit), ai lindi në veriperëndim të Azisë së Vogël. Fillimisht ishte analfabet. Merrej me peshkim dhe të gjitha sa zinte ua ndante të varfërve."},{"t":"p","x":"Tepër besëmirë dhe i shquar në moral, u zbukurua që herët me dhuratën e çudibërjes. Ndaj, episkopi i tij e hirotonisi prift dhe më vonë mitropoliti i të gjithë zonës e bëri hierarkun e Lampsakit, qytetit bregdetar, idhujtar të Dardaneleve."},{"t":"p","x":"Aty ai, duke u dalluar me sukses në virtyt dhe në mrekulli, i ktheu banorët e tij."},{"t":"p","x":"Udhëtoi në Konstandinopojë, mori para dhe leje nga Konstandini i Madh (21 maj), për të rrafshuar altarët e paganizmit dhe të ndërtonte një kishë."},{"t":"p","x":"Mrekullitë e tij kishin të bënin në mënyrë të veçantë me shërimin e të pushtuarve nga demonët, por dhe të sëmundjeve të ndryshme, si p.sh. të një të verbri dhe një gruaje të sëmurë nga kanceri."},{"t":"p","x":"Gjithashtu, vrau duke i fryrë një qeni të egër që iu vërsul; ngjalli tre të vdekur (njëri nga të cilët punonte për ngritjen e kishës dhe e kishte pllakosur karroca e tij, kur me veprim djallëzor i nxitën qetë e tij); hodhi kripë në det dhe vetëm atëherë, pas shumë kohësh, peshkatarët zunë përsëri peshq."},{"t":"p","x":"Kuptoi se shkaku i sëmundjes së rëndë të një mitropoliti ishte tamahqarllëku dhe pashpirtësia e tij dhe ai u bë mirë kur iu bind shenjtit dhe i dha pasuritë e tij lëmoshë."},{"t":"p","x":"U lut në kohë thatësire dhe ra shi, profetizoi dorëzimin e një dhjaku të devotshëm në episkop."},{"t":"p","x":"Fjeti në paqe dhe u varros në kishën që kishte ngritur."},{"t":"p","x":"Parthen, greqisht = virgjëror."}]},{"d":8,"m":2,"blocks":[{"t":"intro","x":"Më 5 të këtij muaji, nderojmë kujtimin e dëshmorit të madh dhe të lavdëruar Theodhor Stratilati, i cili u martirizua ne Irakli të Pontit para vitit 323."},{"t":"li","x":"Kujtimin e profetit Zaharia, nga fisi i Levit."},{"t":"li","x":"Kujtimin e dëshmorit Pergeti."},{"t":"li","x":"Kujtimin e dëshmorëve Niqifor dhe Stefan, të cilët mbaruan jetën me shpatë."},{"t":"li","x":"Kujtimin e dëshmorit Likarioni bashkë me motrat Martha dhe Maria, të cilët u kryqëzuan të gjithë bashkë."},{"t":"li","x":"Kujtimin e shën Agathangjelit, episkop në Damask."},{"t":"li","x":"Kujtimin e oshënarit Sava II, nipi i oshënarit Sava, kryepiskopit të parë të Serbisë (1264-1271)."},{"t":"li","x":"Kujtimin e shën Makarit, episkop në Pafo të Qipros."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Theodhor Stratilati"},{"t":"p","x":"Filiz i Efhaitës së Pontit në bregdetin jugor të Detit të Zi, ishte një oficer i lartë, i lavdëruar në Pontoiraklia. Perandor Likini (308-323) e donte shumë për hir të virtytit, shtatit dhe gojëtarisë së tij. Por nëpërmjet saj kristianizonte pothuajse gjithë qytetin."},{"t":"p","x":"Kur Likini e mësoi këtë gjë, e ftoi në Nikomedi, në veriperëndim të Azisë së Vogël, ku ndodhej. Ai, për t’u martirizuar në vendin e vet dhe për t’u bërë shembull i shpresëtarëve, u hoq sikur luftonte pa e ndalur fenë e re. Ishte në interes pra që të vinte mbreti."},{"t":"p","x":"Ai mbërriti i gëzuar, pasi nëpërmjet Theodhorit do t’i shkëpuste tifozët e Nazareasit. Para turmës e ftoi miqësisht që të sakrifikonte në idhujt e artë që kishte sjellë."},{"t":"p","x":"Stratilati (= Kryegjenerali) duke e paranjohur nga një vizion i natës fundin e tij, iu lut që së pari t’i adhuronte privatisht në shtëpinë e tij."},{"t":"p","x":"Ia dha me kënaqësi, ndërkaq mëngjesin tjetër panë në duart e një të varfri kokën e Afërditës. Shenjti i kishte copëtuar për t’iu ardhur në ndihmë të vobektëve!"},{"t":"p","x":"E arrestuan, e tendosën nga të katër gjymtyrët, e kamxhikuan 750 herë, e goditën në qafë me sfera plumbi, e çorën e dogjën me llambadhe, ia fërkuan plagët me tjegulla, e burgosën pa ngrënë mbi shtatë ditë."},{"t":"p","x":"Më pas e kryqëzuan, shpuan testikujt e tij dhe më pas ia prenë, pasi më përpara fëmijët e shigjetonin në fytyrë, pra i dolën sytë…"},{"t":"p","x":"Në mëngjes 85 ushtarë shkuan për ta zbritur kufomën, por e gjetën të zgjidhur nga një engjëll dhe të shëndetshëm; dhe besuan. U dërguan treqind të tjerë për t’i vrarë, gjithashtu edhe ata besuan tek Krishti. Populli ngriti krye, kështu që monarku nxitoi të urdhërojë që t’i presin kokën."},{"t":"p","x":"Martiri i madh i mbajti besimtarët që të mos bënin veprime të dhunshme për hir të tij, ndërsa sekretarit - dhe biografit - të tij Uari ose Avgari i tha që ta vendoste trupin e tij në çifligun e tij atëror në Efhaita. Transferimi, i cili u realizua mbas katër muajsh, festohet më 8 korrik."},{"t":"p","x":"Disa e konsiderojnë jetën e tij variant të jetës së Tironit me të njëjtin emër (E Shtuna e Parë e Kreshmëve)."},{"t":"p","x":"Theodhor, greqisht do të thotë dhuratë Perëndie."}]},{"d":9,"m":2,"blocks":[{"t":"intro","x":"Më 9 të këtij muaji, nderojmë kujtimin e dëshmorit Niqifor, i cili shkonte në vendin e martirizimit të priftit Saprik, që e mohoi Krishtin në orën e martirizimit të tij, në Antioki mes viteve 259-268."},{"t":"li","x":"Kujtimin e hierodëshmorëve Markeli, episkop i Siçilisë, Filagri, episkop në Kurion të Qipros dhe Pankrati, episkop në Tavromeni, të cilët ishin nxënës të apostullit Petro."},{"t":"li","x":"Kujtimin e dëshmorëve Amoni dhe Aleksandri, nxënës të Origjenit, të cilët u martirizuan në Qipro në shekullin e 3-të."},{"t":"li","x":"Kujtimin e oshënarit Roman çudibërësit nga Antiokia në shekullin e 4-t."},{"t":"li","x":"Kujtimin e hierodëshmorit Petro në Damask, shkrimtar i librave shpirtërorë në shekullin e 8."},{"t":"li","x":"Kujtimin e oshënarit Pankrati, hieromonak në Lavrën e Shpellave të Kievit në shekullin e 13."},{"t":"li","x":"Kujtimin e oshënarëve Niqifor dhe Genadi nga Vologda e Rusisë në shekullin e 16."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Niqifori, martir"},{"t":"p","x":"Niqifori (greqisht = fitimtar) ishte i krishterë nga Antiokia, i cili jetoi në periudhën e perandorit Valerian (253-259)."},{"t":"p","x":"I stolisur me dashurinë më të lartë, ai kishte miqësi të ngushtë me një prift, të quajtur Saprik. Por, papritur, një ditë Sapriku u shndërrua në një armik të betuar të shenjtit për shkaqe të panjohura."},{"t":"p","x":"Niqifori i pafajshëm i kërkoi shumë herë të falur, që të pajtoheshin, herë personalisht dhe herë me anë të ndërmjetësve, por pa rezultat."},{"t":"p","x":"Përpjekja e tij vazhdoi deri në fillimin e një periudhe përndjekjeje, ku ndër të parët kapën Saprikun, i cili pohoi me vendosmëri Shpëtimtarin e si pasojë iu nënshtrua torturës së frikshme të “bulonave”. Duke qëndruar i palëkundur, ai u dënua me prerje të kokës."},{"t":"p","x":"Në vendin e ekzekutimit mbërriti shenjti dhe i ra ndër këmbë, që sakrifica e Saprikut të mos njollosej dhe të mos përlyhej. Zoti ka theksuar, se para se të ofrosh flijimin tënd, meqenëse ke prurë “dhuratën tënde mbi therore” (Matth. 5.23-24) është i domosdoshëm pajtimi me vëllain tënd, që ka diçka kundër teje, qoftë edhe kur tek ty ende ka mbetur shija e hidhërimit të shkaktuar prej tij."},{"t":"p","x":"Por, Sapriku u tregua i ashpër dhe në çastin e fundit kulmor. Atëherë mendja e tij u errësua. Pyeti se përse po e vrisnin. Kur i dhanë përgjigjen, ai e mohoi menjëherë Shpërblyesin!"},{"t":"p","x":"Niqifori nuk mundi ta bindte, që të kthehej prapë tek Krishti, me gjithë lotët dhe lutjet e tij. Atëherë atij iu pre koka, duke zënë vendin e Saprikut në shpalljen e Jisuit, në martirizimin dhe në Agjiologjinë (lista e shenjtorëve) e Kishës sonë."},{"t":"p","x":"Ndaj, me të drejtë apostull Pavli tha: “Nëse jap trupin tim, që të digjem, por nuk kam dashuri, nuk më sjell fare dobi” (I Kor. 13.3). Ndërsa Gojarti: “Asgjë nuk është e barabartë me dashurinë, as vetë martirizimi”!"}]},{"d":10,"m":2,"blocks":[{"t":"intro","x":"Më 10 të këtij muaji, nderojmë kujtimin e hierodëshmorit të shenjtë Harallamb, i cili u martirizua në vitin 211."},{"t":"li","x":"Kujtimin e dëshmorëve Vapti dhe Porfiri, të cilët e torturuan shën Harallambin në fillim, por pastaj besuan tek Krishtin dhe mbaruan jetën e tyre me shpatë."},{"t":"li","x":"Kujtimin e dëshmorëve Enata nga Gaza e Palestinës, Valentina nga Qesaria dhe Pavli nga Qesaria e Palestinës, u martirizuan në fillim të shekullit të 4-t."},{"t":"li","x":"Kujtimin e oshënarit Zinon, postier i letrave të mbretit, i cili jetoi më pas në shkretëtirë në shekullin e 4-t."},{"t":"li","x":"Kujtimin e atit tonë të shenjtë Anastasi II, patriark i Jerusalemit (358- 478)."},{"t":"li","x":"Kujtimin e mbretëreshës Ana, nusja e mbretit Jaroslav I, në Novgorod të Rusisë 1056."},{"t":"li","x":"Kujtimin e oshënarit Prohor nga Lavra e Kievit të Rusisë në vitin 1107."},{"t":"li","x":"Kujtimin e oshënarit Longin i Koriazhemkës, themelues i manastirit me të njëjtin emër në Rusi më 1540."},{"t":"li","x":"Kujtimin e shën Vladimirit dhe Anës, princi dhe princesha e Novgorodit."},{"t":"li","x":"Kujtimin e episkopëve të Novgorodit: Joakimi, Llukai, Gjermani, Arkadhi, Grigori (Gabriel), Martiri, Andoni, Vasili, Simeoni dhe Serapioni."},{"t":"li","x":"Kujtimin e shën Skolastikës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Harallambi, hieromartir, Porfiri, Vapti,"},{"t":"h","x":"tri gra martire"},{"t":"p","x":"Harallambi ishte prift (ose kryeprift) në qytetin Magnezi të Azisë së Vogël, afër Izmirit. Vepronte me guxim, prandaj dhe u arrestua në kohën e Septim Severit (193-211)."},{"t":"p","x":"E duroi me qëndrueshmëri rrjepjen. Duka, si i prishur mendsh, u sul vetë kundër tij, por duart e tij u prenë që në bërryla dhe mbetën të ngjitura në trupin martir!"},{"t":"p","x":"Të pranishmit mbetën si të goditur nga rrufeja dhe kërkuan ndjesë nga Harallambi (ose Harallambo) 113 - vjeçar. Atëherë shëroi dukën, i cili dhe u pagëzua."},{"t":"p","x":"Besuan dhe xhelatët, Porfiri dhe Vapti (apo Dhavkti) dhe tri gratë. Mbasi u pagëzuan që të pestë, iu prenë kokat (festohen së bashku me hierodëshmorin). Atëherë turmat pagëzoheshin dhe shumë u shëruan në mënyrë të mbinatyrshme nga plaku."},{"t":"p","x":"Më pas, sipas urdhrit të perandorit, i mbërthyen në shpinë gozhda dhe e sollën ne Antioki (ka mundësi për Antiokinë në Meandri dhe jo Antiokinë e Madhe) të Azisë së Vogël të hipur në kalë duke e tallur, derisa kafsha reagoi dhe i shau me zë njeriu!"},{"t":"p","x":"Më pas i shkuan një hell në gjoksin e tij dhe e hodhën në zjarr, por nuk u cenua."},{"t":"p","x":"Përpara Sevirit shëroi një të demonizuar dhe ngjalli një të vdekur, kështu që ai (mbreti) u çudit. Megjithatë, duke qenë zemërgur urdhëroi që t’i thyenin me gurë nofullat dhe t’i digjnin mjekrën, por më kot. Sapo blasfemoi, u dënua derisa u pendua."},{"t":"p","x":"Po mbas një muaji u egërsua përsëri, dhe pavarësisht nga këshillat e bijës së tij, Galinisë, e cila ishte e krishterë, urdhëroi dhe i vunë atletit më shumë se njëqindvjeçar kapistër në gojë si kafshë dhe e shëtisnin nëpër qytet. Më në fund vendosën t’i prisnin kokën. Ndërkohë, shtylla e thatë në të cilën u mbështet lëshoi degë! Ndërkaq erdhi Zoti dhe mori frymën e tij, para se t’i prisnin kokën (mundet në vitin 202)."},{"t":"p","x":"Shenjti nderohet gjerësisht si mbrojtës nga epidemitë madje dhe nga murtaja, kurse koka e tij ruhet në Manastirin e Shën Stefanit në Meteora."},{"t":"p","x":"Harallamb greqisht = ai që shkëlqen nga hareja (gëzimi)."},{"t":"h","x":"Ana suedezja"},{"t":"p","x":"Kishte tre emra: Ingjegjerdha ishte ai pagan, Irini, emri i pagëzimit, dhe Ana, emri murgjëror."},{"t":"p","x":"Ishte bijë e mbretëreshës Estridha dhe e të urtit, trim dhe të vendosur Olaf Sketkonung, mbretit të parë të krishterë të Suedisë, të parë si nga pikëpamja kohore ashtu dhe nga ajo e vlerave. U pagëzua rreth vitit 1000."},{"t":"p","x":"Ishte inteligjente, me prirje poetike, zemërmirë, e zgjuar, guximtare, aspak mendjemadhe - e mrekullueshme."},{"t":"p","x":"Kur nuk mundi t’i mbushte mendjen Olafit t’i jepte zgjidhje luftës së nderë dhe shkatërrimtare me norvegjezët, ishte e gatshme të martohej me mbretin e tyre, Olaf Haraldson (shenjt i Perëndimit)."},{"t":"p","x":"Babai i saj, për të mos shkaktuar pakënaqësi tek këshilli i tij, fillimisht pranoi. Por shumë pak kohë para dasmës (1015) ndërroi mendje dhe ia premtoi Jeroslavit, princit të Novgorodit, që ndodhet në jug të Petropolit në Rusi."},{"t":"p","x":"Norvegjezët pranuan, dhe monarkun e tyre e mori motra tjetër e saj e thjeshtë, Astridha dhe kështu iu dha fund grindjeve. Ka shumë mundësi që Jeroslavi ta ketë kërkuar vajzën për arsye politike, në perspektivën e përplasjes me atin e tij, shën Vladimirin (15 korrik), por ai (Vladimiri) fjeti shpejt (1015)."},{"t":"p","x":"Më 1016 shenjtorja arriti në Novgorod, që së bashku me Kievin ishin vendet e ndenjes së oborrit rus. Princesha e Madhe (d.m.th mbretëresha) e mençur, ndikoi thellë në politikën e burrit të saj, të cilin e ndoqi disa herë në betejë! Njëherë, madje me dredhi, ajo u kap rob, por ndërhyri dhe u ra dakord për armëpushim."},{"t":"p","x":"Shpresëtarja paqebërëse Irini (= paqe) bëri që më në fund midis Rusisë, Suedisë dhe Norvegjisë të sundonte paqja e përhershme."},{"t":"p","x":"Përveç dhjetë fëmijëve të saj rriste jetimë, si dhe fëmijë princash të huaj. Emri i saj u lidh dhe me Manastirin e Shën Irinit, që u ngrit (1037) për nder të saj, si dhe me themelimin e kishës së Shën Sofisë, gjithashtu në Novgorod."},{"t":"p","x":"Fjeti atje në Novgorod (10.2.1056), pasi u bë murgeshë me emrin Ana. Festohet dhe më 4 tetor së bashku me të birin e saj, shën Vladimirin (nipin e Vladimirit të Parë). Lipsanët e paprishur të të dyve kanë qenë në kishën e Shën Sofisë deri në revolucionin e vitit 1917."},{"t":"h","x":"Zinon postieri"},{"t":"p","x":"E kishte origjinën nga Kapadhokia ose, sipas një informacioni tjetër, nga aristokratë prej Pondit (në Veri të Azisë së Vogël), me pasuri të madhe. Mësoi pranë shën Vasilit (1 janar)."},{"t":"p","x":"Shërbeu në trupën e korrierëve mbretërorë të perandor Ualit (364- 378), mbas vdekjes së të cilit e la gradën ushtarake dhe u ushtrua në mënyrë të pangjashme brenda një varri të largët."},{"t":"p","x":"“Qelia” e tij nuk kishte asnjë mobilje apo enë. Flinte në bar mbi gurë, hante pak bukë, që ia sillnin çdo dy ditë dhe furnizohej me ujë nga një distancë e largët për hir të ushtrimit të ashpër."},{"t":"p","x":"Përpjekja e ngriti në gjendjen e përulësisë dhe të lutjes, ashtu siç na e sjell biografi bashkëkohës okular, Theodhoriti i Kirit."},{"t":"p","x":"Gjithashtu, gjatë invazionit të isaurëve nëpërmjet lutjes verboi barbarët gjakatarë e ata nuk gjenin hyrjen e banesës së tij. Ndërkohë ai shihte tre të rinj të dëbonin turmën."},{"t":"p","x":"Fjeti pra në paqe mbas pak kohe. Oshënarin e nderojnë si mbrojtësin e Postës."},{"t":"p","x":"Zinon, rrjedh nga perëndia Zeusi."},{"t":"h","x":"Prohor çudibërësi i Lavrës së Shpellave të Kievit"},{"t":"p","x":"Gjatë mbretërimit të Sviatopolk Iziaslavoviç, i njohur për mizorinë dhe padrejtësitë e tij, populli i Kievit hoqi shumë vuajtje. Dhe kjo vuajtje u intensifikua edhe më shumë nga fiset nomade përreth, si ai i Polovtsianëve. Sulmet e tyre, rrëmuja civile, vjedhjet dhe përçarjet e brendshme shkaktuan uri të madhe në vend. Në këtë kohë Prohori erdhi nga Smolensku për në Lavër dhe i kërkoi igumenit Joan ta qethte murg e të bëhej pjesë e vëllazërisë. Dallohej nga të gjithë, sepse veshja e tij ishte tepër përçmuese e të varfër. Në këtë kohë, një uri e madhe pllakosi vendin, i lumuri Prohor mblodhi atë pak ushqim që hante dhe ua dha të uriturve. Atëherë të gjithë vëllezërit mblodhën bukën që kishin, edhe pse ishte e prishur për ta ngrënë. Por për çudi, të gjithë sa hëngrën nga kjo bukë, iu duk e ëmbël."},{"t":"p","x":"Një herë, një nga vëllezërit shkoi tek qelia e Prohorit ku grumbullonte bukën dhe mori fshehtazi pak nga buka e thartë dhe e prishur. Kur e hëngri, i shijoi se ishte e ëmbël. Ia rrëfeu igumenit se Prohori e kishte kthyer bukën e hidhur në të ëmbël. Për ta parë këtë vetë, igumeni dërgoi dikë tek shenjti që t’i kërkonte bukë me bekimin e tij, dhe më pas dërgoi dikë t’i rrëmbente fshehur bukë shenjtit. Ai që e kishte marrë bukën me bekim nga duart e shenjtit tha se buka ishte e ëmbël, ndërsa tjetri e kishte të zezë dhe të hidhur. Prohori i bekuar, kur pa mjerimin e popullit, mblodhi frytin e frashrit dhe u lut nxehtësisht që Perëndia ta kthente në kripë, dhe kështu u bë. Kripa u mor dhe u përdor për tregti, gjë që solli shumë të ardhura në popull. Kur princi mësoi për këtë e thirri në oborr Prohorin. Njohu shenjtërinë e tij përmes mrekullive dhe kjo bëri që Sviatopolku të vizitonte manastirin dhe të pendohej. Premtoi se kurrë nuk do ta dhunonte kishën. Pas kthimit të princit, Prohori u dha plot me zell në lutjen e pandërprerë. U sëmur dhe ndjeu fundin e tij. I dërgoi mesazh Sviatopolkut që të vinte, sepse fundi i tij po afrohej. Princi kur mori lajmin e tij, braktisi ushtrinë dhe nxitoi të takonte."},{"t":"p","x":"Në shtratin e vdekjes, shenjti këshilloi princin, i dha faljen e mëkateve dhe më pas fjeti. Princi varrosi trupin e shenjtë të Prohorit dhe u kthye në ushtri. Në betejën që pati me Polovtsianët korri fitore dhe ia aneksoi territorin e tyre Kievit."}]},{"d":11,"m":2,"blocks":[{"t":"intro","x":"Më 11 të këtij muaji, nderojmë kujtimin e hierodëshmorit Vlash, kryepiskop i Sebastisë në vitet 308-324."},{"t":"li","x":"Kujtimin e shtatë dëshmoreve gra dhe dy djem, të cilët u martirizuan bashkë me shën Vlashin."},{"t":"li","x":"Kujtimi e gjetjes së lipsanit të profetit Zaharia, ati i shën Joan Pararendësit në fshatin Kofar të Palestinës gjatë mbretërimit të Theodhosiut të dytë (408-450)."},{"t":"li","x":"Kujtimin e mbretëreshës Theodhora, nusja e mbretit Theofil, e cila soli përsëri ikonat e shenjta në Kishën Orthodhokse në Konstandinopojë në vitin 867."},{"t":"li","x":"Kujtimin e shën Gabrielit, mbreti i Rusisë në vitin 1138."},{"t":"li","x":"Kujtimin e oshënarit Dhimitri i Prilukit, çudibërës, asket bashkë me shën Sergjin në Radonezh të Rusisë në viti 1392."},{"t":"li","x":"Kujtimin e dëshmorit të ri Gjergji nga Serbia, i cili u martirizua në zjarr në Sofia të Bullgarisë në 1515."},{"t":"li","x":"Kujtimin e shën Vsevolodit, princ i Pskovit."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Vlashi, hieromartir, shtatë gra, dy fëmijë martirë"},{"t":"p","x":"Vlashi ishte episkop i qytetit armen të Sevastisë (në Verilindje të Qesarisë të Kapadhokisë), qetësohej në një mal gjatë përndjekjes së perandorit Likini (308-323)."},{"t":"p","x":"Mjek por kryesisht mrekullibërës, shëronte shumë kafshë të egra, që mblidheshin në shpellën e tij! Gjahtarët idhujtarë të cilët i panë të habitur, u afruan, e zbuluan dhe e spiunuan."},{"t":"p","x":"Shenjti ndiqte me gëzim togën që e arrestoi. Në rrugë shëroi me lutjen e tij djalin e vetëm të një nëne, e cila iu përgjërua që ta çlironte birin e saj në prag të vdekjes tashmë nga një halë peshku që ishte ngulur në ezofagun e tij."},{"t":"p","x":"Atëherë hierarku kërkoi nga Perëndia që në raste të tilla të shërohen ata që i luten - dëgjohet dhe gryka shërohet, pasi në përputhje me një himn të tij shpata i preu grykën, siç do ta shohim; pra nderohet si shëronjës i sëmundjeve të grykës."},{"t":"p","x":"U burgos në Sevasti. Meqenëse në mënyrë të përsëritur nuk pranonte që të sakrifikonte, iu nënshtrua herë pas here torturave, d.m.th. goditje, varje dhe shqyerje brinjësh."},{"t":"p","x":"E ndoqën shtatë gra, të cilat pohuan Krishtin. Ato i arrestuan. Kur me marifet gratë i hodhën idhujt në liqenin e Sevastisë, u shqyen me thonj të hekurt, por në vend të gjakut rrodhi qumësht, në të njëjtën kohë engjëjt u jepnin kurajë. Më përpara nuk ishin joshur nga veshjet e çmuara që u kishin ofruar idhujtarët. Më pas i futën në furrë, por ajo u shua menjëherë. Në fund iu prenë kokat."},{"t":"p","x":"Hierodëshmori u hodh në liqen, por qëndroi i padëmtuar mbi ujë, ndërkohë që u mbytën me dhjetëra ushtarë, të cilët u përpoqën që të bënin të njëjtën gjë."},{"t":"p","x":"Gjithashtu iu pre koka dhe dy fëmijëve të një prej shtatë grave martire, të cilat deklaruan besimin e tyre tek Jisui. Festohen edhe këta të dy së bashku me kryepriftin dhe dëshmoret. Emri Vlash ndoshta vjen nga balsami."}]},{"d":12,"m":2,"blocks":[{"t":"intro","x":"Më 12 të këtij muaji, nderojmë kujtimin e shën Meletit, kryepiskop i Antiokisë, i cili ishte kryetar në Sinodin e Dytë Ekumenik në vitin 381."},{"t":"li","x":"Kujtimin e oshënares Maria, e cila jetoi në një manastir burrash si burrë me emrin Marini bashkë me atin e saj Evgjeni në shekullin e 6."},{"t":"li","x":"Kujtimin e atit tonë Andon II, kryepiskop i Konstandinopojës (901-983) dhe themelues i një manastiri që mban emrin e tij."},{"t":"li","x":"Kujtimin e dëshmorëve Satornini dhe Plotini, të cilët mbaruan jetën e tyre me shpatë."},{"t":"li","x":"Kujtimin e atit tonë Aleks çudibërësit, episkop i Vladimirit (1350-1354) dhe më pas kryepiskop i Kievit dhe gjithë Rusisë (1354-1378)."},{"t":"li","x":"Kujtimin e dëshmorit të ri Kristo kopshtari nga Shqipëria, i cili jetoi në Konstandinopoja dhe u martirizua atje për Krishtin në vitin 1784."},{"t":"li","x":"Kujtimin e shën Vasianit, igumen i Manastirit të Riabovskit në Ugliç."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Kristo kopshtari"},{"t":"p","x":"U ushtrua (martirizua) më 12.2.1748. Ishte shqiptar. Në moshën 40 - vjeçare shkoi refugjat në Konstandinopojë ku u bë kopshtar."},{"t":"p","x":"Një ditë kur kishte dalë për të shitur mollë në pazar, me një blerës turk nuk ra dakord për pazarin dhe filluan të grindeshin. Turku, që të hakmerrej kundër tij, shpifi se gjoja i kishte thënë që të ndryshonte besimin e tij."},{"t":"p","x":"Menjëherë e çoi te gjykatësi dhe sajoi dëshmitarë të rremë, që vërtetonin fjalët e tij. Kristoja me guxim deklaroi se ishte i krishterë, se nuk kishte thënë asgjë të tillë dhe se nuk e ndryshonte fenë e tij pavarësisht nga mijëra e mijëra dënime që mund të merrte."},{"t":"p","x":"Kadiu urdhëroi dhe e goditën pa mëshirë me shkop në kokë sa u gjakos. Pastaj e futën në burg, ku rrinte me këmbët e fiksuara në “drurin” torturues, ku nuk mund t’i lëvizte dot - ishte një torturë e tmerrshme."},{"t":"p","x":"Në burg ishte dhe dijetari i dëgjuar Konstandin Dhapontes, që më vonë u bë murg me emrin Qesar. Ky, më vonë shkroi martirizimin e shenjtorit. Me ndërhyrjen e tij këmbët iu liruan. Gjithashtu i solli ushqim që të merrte fuqi, por dëshmorit të ri nuk i mjaftonte flijimi i jetës së tij që po afrohej, por deshi të ofronte një sakrificë të vogël më tepër: të rrinte pa ngrënë e pa pirë për Jisuin! I dha Dhapontes një mprehës çeliku me vlerë që kishte në rripin e tij, që ta shiste për të kryer Liturgjitë për shpirtin e tij."},{"t":"p","x":"Më në fund i prenë kokën dhe kështu fitoi kurorën e shumëdëshiruar në Mbretërinë e Qiejve dhe një vend nderi në Agjiologjinë e Kishës. “Kristoja, duke u prerë për dashurinë e Zotit, u bë kopshtar i vendit të Edenit [Parajsës]”, sipas himnologjisë."},{"t":"h","x":"Meleti i Antiokisë"},{"t":"p","x":"Filiz i pasur dhe zyrtar i Armenisë në Azinë e Vogël, në fillim të shekullit të 4-t, studioi thellë filozofinë dhe teologjinë."},{"t":"p","x":"Më 358 heretikët, “të Ngjashmit”, e zgjodhën pasardhës të hierarkut të Sevastisë, Efstathit, të cilin e kishin shfronësuar. Por për shkak të reagimeve u tërhoq në Veria të Sirisë dhe nuk ushtroi shërbimin e tij."},{"t":"p","x":"Kështu, më 360, arianitët, të cilët e konsideronin të të njëjtit besim me ta, e propozuan në fronin e Antiokisë. Ranë dakord edhe orthodhoksët - marrëveshje e paparë - dhe gjithashtu e pranuan idhujtarët dhe hebrenjtë!"},{"t":"p","x":"Por u tregua orthodhoks në fjalimin e tij gjatë fronëzimit, ku ai përdori tre gishtërinjtë e dorës për të shprehur dogmën e Trinisë së Shenjtë. Në zgjedhjen e tij, shumë aktiv ishte treguar shën Eusebi i Samosatës (22 qershor)."},{"t":"p","x":"Heretikët pra, pasi nuk e bindën, u vunë në veprim dhe perandori Konstand (337-361) e internoi, tridhjetë ditë pas zgjedhjes së tij, në atdheun e tij, pra në Melitini të Armenisë (361). Në vend të tij u dorëzua një arianit."},{"t":"p","x":"Por rrezatimi i virtytit të omologjetit qetësidashës kishte krijuar shumicë “meletiane”, d.m.th. luftëtarë të përkushtuar, pasues të tij. Por, pala e orthodhoksëve të rreptë nuk e njohu për shkak të propozimit të tij si kryepiskop nga arianët. Këto përfshihen në skizmën antiokiane, të quajtur jo saktë “meletiane”. Jo saktë, sepse fazat e shumëllojshme të saj zgjatën një shekull e gjysmë (330-483), dhe kishte ndërthurje dhe të grupeve të tjera të nuancave të ndryshme heretike të qytetit të madh të vuajtur."},{"t":"p","x":"Shenjti u kthye më 362, u internua sërish më 365, rierdhi më 367 me sa duket, për t’u dëbuar përsëri më 371 dhe të kthehet më 379. Një sinod i madh që ai mblodhi më 379, shpalli dogmën orthodhokse."},{"t":"p","x":"U sëmur dhe ndërroi jetë (maj 381) ndërsa kryesonte, për hir të respektit të përgjithshëm për personalitetin e tij udhëheqës, Sinodin II Ekumenik në Konstandinopojë. U varros me nderime të veçanta."},{"t":"p","x":"Meleti, greqisht = studiuesi."}]},{"d":13,"m":2,"blocks":[{"t":"intro","x":"Më 13 të këtij muaji, nderojmë kujtimin e oshënarit Martinian në shekullin e 5-të bashkë me dy gratë e shenjta Zoja dhe Fotina."},{"t":"li","x":"Kujtimin e apostujve Akila dhe gruaja e tij Priskila, bashkëpunëtorë të apostull Pavlit."},{"t":"li","x":"Kujtimin e shën Evlogjit, patriark i Aleksandrisë në vitet 579-607."},{"t":"li","x":"Kujtimin e oshënarit Simeon, ati i shën Savës, kryepiskop i Serbisë, i cili jetoi 5 vjet në Malin e Shenjtë në Manastirin e Hilandarit dhe fjeti në paqe në vitin 1200."},{"t":"li","x":"Kujtimin e dy dëshmorëve atë e bir, të cilët i kryqëzuan."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Martiniani, oshënar"},{"t":"p","x":"Në moshën 18-vjeçare doli në një mal të vendlindjes së tij, në Qesari të Palestinës (në fillim të shek. të 5-të) dhe përparoi aq shumë saqë shumë njerëz vraponin tek ai për t’u shëruar në trup dhe në shpirt."},{"t":"p","x":"Satanai e luftonte me të gjitha mënyrat, madje, duke iu shfaqur edhe si dragua. Një herë ai nxiti ambicien e një prostitute, e cila u mburr se do ta bënte për vete."},{"t":"p","x":"Prandaj, ajo u vesh si varfanjake dhe një natë me shtrëngatë bërtiste jashtë shpellës së tij: “Më shpëto; humba rrugën, do të më hanë egërsirat; ti do ta kesh gjynahun”!"},{"t":"p","x":"Mëdyshja ishte e tmerrshme: do të rrezikohej ose ajo trupërisht, ose ai shpirtërisht! U lut dhe pasi e mori brenda, hyri thellë në shpellë."},{"t":"p","x":"Në mëngjes e pa të veshur me rroba të kushtueshme dhe me stoli demoniake që kishte sjellë me vete. Lajkat për bukurinë e tij dhe argumentet për martesën nga Shkrimi i Shenjtë (!) së bashku me prekjet epshndjellëse, e lëkundën dhe prandaj doli jashtë për të parë nëse po vinin pelegrinët e tij dhe e kapnin në flagrancë."},{"t":"p","x":"Atëherë Perëndisë i erdhi keq për asketizmin e tij 26 - vjeçar dhe i frymëzoi pendesën. Prandaj ndezi një zjarr dhe hyri në të dy herë, derisa iu dogjën këmbët, ndërsa fliste me vete për zjarrin e Ferrit."},{"t":"p","x":"Gruaja e pacipë u trondit, flaku në zjarr stolitë dhe kërkoi falje duke vajtuar. Me nxitjen e tij ajo u bë murgeshë deri në vdekje, d.m.th dymbëdhjetë vjet, në Betlehem, në manastirin e Paulës, nxënëses së oshënar Jeronimit (15 qershor), dhe bëri mrekulli!"},{"t":"p","x":"Omologjeti i virtytit, pasi u shërua pas shtatë muajve të mundimshme, u vendos në një ishull të pabanueshëm pa pasur strehë mbi kokë. Një kapiten anijeje vinte herë pas here dhe i sillte ujë, bukë dhe lëndë të parë për t’i bërë litarë. Një herë u rrezikua nga një shtrëngatë deti."},{"t":"p","x":"Pas dhjetë vjetësh pësoi të njëjtën gjë: Një bukuroshe 25-vjeçare ishte duke u mbytur pranë ishullit, ai e shpëtoi, por vetë ra në det, ndërsa dy delfinë e nxorën në tokë!"},{"t":"p","x":"Për t’iu shmangur “sulmeve” të reja, dy vjet rresht lëvizte vazhdimisht nga një vend te tjetri. Dhe kështu fjeti në Athinë. Ndërsa vajza nuk pranoi ta çonte kapiteni i anijes në vendin e saj, por qëndroi aty për të vazhduar jetën e oshënarit, derisa vdiq pas gjashtë vjetësh."}]},{"d":14,"m":2,"blocks":[{"t":"intro","x":"Më 14 të këtij muaji, nderojmë kujtimin e oshënar Afksentit nga Kalqidhona e Thrakës në shekullin e 5-të."},{"t":"li","x":"Kujtimin e hierodëshmorit Filimon, episkop në Gaza të Palestinës."},{"t":"li","x":"Kujtimin e oshënar Maronit në shekullin e 4-t."},{"t":"li","x":"Kujtimin e oshënar Avramiut, episkop në Harran të Palestinës, i cili jetoi në vitin 350-422."},{"t":"li","x":"Kujtimin e oshënarit Kiril, i cili bashkë më vëllain e tij, shën Metodin, ndriçuan sllavët në vitet 827-869."},{"t":"li","x":"Kujtimin e oshënarit Isaak i Mbylluri, në Lavrën e Shpellave të Kievit në vitin 1190."},{"t":"li","x":"Kujtimin e dëshmorit i ri Nikolla nga Korinthi i Greqisë, i cili u martirizua në Konstandinopojë në vitin 1554."},{"t":"li","x":"Kujtimin e hierodëshmorit Damiani i Ri, i cili u martirizua në Larisa në vitin 1568."},{"t":"li","x":"Kujtimin e dëshmorit i ri Gjergji rrobaqepësi nga Mitilina, i cili u martirizua në Konstandinopojë në vitin 1693."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Isaaku i marrë për Krishtin i Lavrës së Kievit"},{"t":"p","x":"Jetoi në gjysmën e dytë të shekullit të njëmbëdhjetë. Më përpara ishte një tregtar i pasur nga qyteti i Toropets, por kishte ndjerë thirrjen e lartë për murgjëri. Shpërndau pasurinë që kishte, mori kryqin dhe ndoqi Krishtin. Perëndia e udhëhoqi shërbëtorin e tij të përulur në Shpellat e Kievit ku u qeth murg nga shën Andoni. Ishte një enë e zgjedhur për punë të veçanta. Në vend të rasos mbante një rrobë të thurur me qime kali dhe kështu filloi të ushtrohej ashpër. Më vonë, mori një lëkurë dhie bëri një xhaketë të ngushtë. Kërkoi bekimin që të jetonte si i mbyllur. Shkoi në një shpellë të vogël 2 m2 dhe filloi betejën e lutjes. Dritarja e qelisë ishte kaq e vogël sa dora e një njeriu me vështirësi mund të futej. Jetoi kështu për shtatë vjet dhe kurrë nuk doli në dritë. Nuk u shtri kurrë, por dremiste ndonjëherë më këmbë. Në mbrëmje fillonte metanitë dhe vazhdonte kështu deri në mesnatë."},{"t":"p","x":"Një herë, Isaaku ishte ulur dhe kandili po fikej. Papritur qelia u mbush me dritë të shkëlqyer. Dy persona të shndritshëm erdhën atje. “Isaak!” thirrën ata, “Ne jemi dy engjëj të Krishtit, ai po vjen drejt teje! Përkulu para tij!” Shenjti nuk e kuptoi këtë veprim të të ligut dhe ai ra në gjunjë dhe i përshëndoshi, si të ishte Krishti. Demonët thirrën “Je i yni, Isaak”. I gjithë korridori i qelisë u mbush me të tillë gjoja engjëj. Demoni që iu shfaq si Krishti tha: “Merrni fyell, cimbale dhe psalni, dhe Isaaku le të kërcejë me ne”. Dhe ata filluan të luajnë me të. Aq shumë e munduan sa e lanë gjysmë të vdekur. Pastaj demonët e lanë dhe u larguan. Kur shën Andoni shkoi në dritaren e Isaakut dhe tha lutjen, askush nuk iu përgjigj nga brenda, dhe mendoi se ndoshta avai kishte fjetur në Zotin. Shkuan në qeli edhe vëllezërit, dhe e nxorën prej saj duke menduar se kishte vdekur tashmë. Kur e vunë nën dritën e diellit, ai dha shenja jete. Por shën Theodhosi e kuptoi se kjo ishte një punë e demonëve dhe e mori Isaakun me vete për ta vënë në një shtrat në një nga qelitë e manastirit."},{"t":"p","x":"Shën Andoni u kujdes për të. Isaaku ishte kaq i paralizuar sa nuk mund të lëvizte, madje as të fliste për dy vjet me radhë. Të gjithë luteshin për asketin e mashtruar. Pas tre vjetësh, Isaaku filloi të flasë e të dëgjojë, ashtu si një fëmijë i vogël filloi të hedhë edhe hapat e tij të parë. E mbante përkrahu një nga vëllezërit. Por në fund, shën Theodhosi tha: “Le ta lemë të hajë vetë”. Për një jave, Isaaku nuk hëngri bukë, por më pas filloi pak e nga pak."},{"t":"p","x":"Me kalimin e kohës, ai doli nga vuajtja që i shkaktuan demonët dhe rifilloi betejën e tij. U kthye në shpellë dhe me bekimin e igumenit filloi udhën e vështirë të të marrëve në Krishtin. Filloi të shërbejë në kuzhinë si ndihmëskuzhinier. Një ditë kuzhinieri tallej me të dhe i thoshte se atje pranë ishte një korb dhe e urdhëroi me përbuzje të shkonte e ta kapte. Isaaku, i nënshtruar edhe në gjënë me të vogël, shkoi, dhe për çudi u kthye me korbin në dorë. Kuzhinieri u çudit dhe u mrekullua nga kjo ngjarje të cilën ia raportoi igumenit."},{"t":"p","x":"Që të gjithë filluan ta respektonin Isaakun. Demonët i njihte me një fluturim. Për tre vjet të tjera luftoi me demonët dhe tallej me ta. Vitin e fundit të jetës, jetoi në kreshmë të ashpër. U sëmur në shpellë dhe fjeti tetë ditë më vonë më 14 shkurt 1090 kur igumen ishte ava Joani. Lipsani i tij gjendet në shpellën e shën Andonit."},{"t":"h","x":"Avrami i Kares"},{"t":"p","x":"Lindi në Kiri të Eufratit rreth vitit 350 dhe murgëroi që i ri. Si rezultat sidomos i qëndrimit mbinjerëzor në këmbë vuajti një periudhë kur ecte."},{"t":"p","x":"Luajti me të tijët rolin e tregtarit të arave dhe morën me qira një shtëpi në një qytezë shumë pagane të Libanit."},{"t":"p","x":"Ndërsa po meshonin me zë të ulët, iu kundërvu një hordhi dhe u vu të mbulojë shtëpinë duke hedhur kubikë dheu!"},{"t":"p","x":"Meqenëse po vazhdonin adhurimin të patronditur, edhe pse po asfiksoheshin, i nxorën dhe i urdhëruan të ikin."},{"t":"p","x":"Në moment arritën tagrambledhësit dhe po silleshin dhunshëm, derisa Avrami u bë garant se do paguante për të gjithë. Shkoi në Emesa, mori hua dhe pagoi, kështu egërsirat e tronditura u zbutën."},{"t":"p","x":"Ndërtuan një kishë, kërkuan dhe ai u hirotonis prift për ta. Pasi i forcoi në besim tre vjet, u kthye në shkretëtirë."},{"t":"p","x":"Më pas u bë episkop në Kares, Harran biblike të Mesopotamisë (Gjeneza 11.31). Ishte e përmendur për singritizmin (d.m.th. përzierje idesh [fetare]) e saj, por e shndërroi në shumë orthodhokse me fjalën, jetën, dhe kujdesin e tij."},{"t":"p","x":"Si kryeprift mbahej tepër i rreptë. Konsideronte të panevojshme bërjen e bukës, krevatin, zjarrin, ujin! Flinte shumë pak, dhe në stol, për ushqim dhe pije ekskluzivisht kishte lakra të pagatuara të stinës apo pemë."},{"t":"p","x":"Ndërkaq mirëpriste si Abrahami, bile i nxiste të hanin mirë, pa shijuar vetë asgjë. Ushtronte dhe punë sociale si gjykatës i kundërshtarëve."},{"t":"p","x":"Perandori shën Theodhosi II (29 korrik) e ftoi në Konstandinopojë dhe e nderoi shumë dhe me shpresëtari së bashku me mbretëreshat - nënkuptohen sigurisht motra e tij shën Pulqeria (17 shkurt) dhe bashkëshortja e tij shën Evdhoqia (13 gusht). E prekën që të merrnin bekim dhe iu lutën, megjithëse nuk dinte greqisht."},{"t":"p","x":"Fjeti shpejt (pak mbas 422). Monarku dëshironte ta mbulonte atje, por përfundimisht mbajti një rrobë të tij të vjetër për bekim dhe shoqëroi trupin e tij deri në port. U vendos në Kares. Ngado që kaloi bëhej alarm! Do t’i rrëmbenin rreckat e tij, nëse nuk do të rrezikoheshin prej rojeve të tij që mbanin shkopinj."},{"t":"p","x":"Avrami, hebraisht rrjedh nga Avraam = ati i shumë njerëzve."},{"t":"p","x":"Simeon (Nemanja) Mirovliti, themeluesi i Manastirit të Hilandarit * Shën Stefan Nemanja lindi më 1114 në një provincë të Zetas, Mali i Zi sot, e cili ishte nën varësi latine. Që në çastin kur prindërit e tij mundën të shkonin në Serbi, e pagëzuan fëmijën dhe e rritën me dashuri për besimin dhe virtytet. Atit të tij iu besua qeverisja e një province, dhe falë aftësive të tij qeverisëse u bë princi i madh i të gjithë Serbisë (1165), të cilën mundi ta mblidhte në një mbretëri të vetme. Ai ishte themeluesi i dinastisë së Nemanidës, e cila do të qeveriste mbi gjithë popullin serb për 200 vjet (1172-1371) dhe do t’i jepte Kishës Serbe një numër të madh shenjtorësh.2"},{"t":"p","x":"Gjatë mbretërimit të tij, iu desh të përballej me vëllezërit e tij rivalë, të cilët e burgosën për shkak të Orthodhoksisë. Por falë besës së tij të pathyeshme dhe me ndihmën e dukshme të martirit të madh e të shenjtë Gjergj Trofeprurësit, fitoi mbi armiqtë e tij. Atëherë mblodhi një sinod për ta pastruar vendin nga flaka e herezisë së bogomilëve. Me ndihmën e gruas së tij Ana, ndërtoi shumë kisha dhe manastire dhe dhuroi pasuri për shenjtërore të mëdha të krishterimit. Kur e forcoi pavarësinë e gjendjes së tij kundrejt Bizantit dhe siguroi një mirëorganizim të Kishës, ndoqi shembullin e birit të tij Rastko-Sava dhe mori veshjen murgërore në Manastirin e Studenicës (1199) me emrin Simeon, ndërsa gruaja e tij u tërhoq në një manastir grash dhe mori emrin Anastasia."},{"t":"p","x":"Pas dy vjetësh, shkoi në Mal të Shenjtë pranë djalit të tij, në Manastirin e Vatopedit, dhe u bë nxënës i përulur i të birit. Megjithëse mosha nuk i premtonte shumë, ai imitoi zellin e Savës për lutjen. Të dy ndihmuan në zbukurimin e manastirit; më pas nga rrënojat ngritën manastirin e bukur e të madh të Hilandarit. Tetë muaj pas vendosjes në Hilandar, Simeoni u sëmur. Thirri djalin e tij Savën, i dha lamtumirën, kërkoi falje para të gjithë vëllezërve të tjerë me sytë e fiksuara në ikonën e të Tërëshenjtës duke thënë këto fjalë: “Çdo frymë le të lavdërojë Zotin”(Ps. 148)."},{"t":"p","x":"Ishte 13 shkurt i vitit 1200. Pak kohë më pas, trupi i tij filloi të nxjerrë një erë të mirë, e cila kreu mrekulli të shumta. Lipsani i tij u çua në Serbi nga shën Sava dhe ndihmoi për pajtimin e dy vëllezërve të tjerë: Stefanin dhe Vukanin. Kur princi Stefan donte ta mohonte Orthodhoksinë për arsye politike (1216), era e këndshme që buronte nga trupi i shenjtit nuk doli më; por pas letrës që shën Sava ia drejtonte të atit dhe që u lexua para varrit të tij, shenjti tregoi përsëri mbrojtjen e tij për popullin."},{"t":"p","x":"Nga varri bosh i shën Simeonit, që mbeti në Hilandar, mbiu mrekullisht një vresht, ku kokrrat e rrushit të thara shpërndahen ende sot në botë për bekimin e çifteve që nuk bëjnë fëmijë."},{"t":"p","x":"1. Përveç shën Stefanit-Simeonit, gruas së tij dhe birit të tyre shën Sava (14 janar), djali tjetër i tyre, pasues i fronit, Stefani i II i Pari i Kurorëzuar u bë edhe ai murg dhe u nderua si shenjtor (24 shtator). Djali i këtij të fundit, Stefani i III u bë edhe ai murg."}]},{"d":15,"m":2,"blocks":[{"t":"intro","x":"Më 15 të këtij muaji, nderojmë kujtimin e apostull Onesimit, nxënës i apostull Pavlit."},{"t":"li","x":"Kujtimin e dëshmorit Majori, i cili u martirizua në Gaza të Palestinës mes viteve 285-305."},{"t":"li","x":"Kujtimin e shën Theogniut, episkop i Bethelias."},{"t":"li","x":"Kujtimin e shën Anthimit të Hios."},{"t":"li","x":"Kujtimin e shën Dalmatit të Siberisë."},{"t":"li","x":"Kujtimin e oshënarit Efsevi nga Siria në shekullin e 5-të."},{"t":"li","x":"Kujtimin e oshënarit Pafnuti i Mbyllur, në Lavrën e Kievit të Rusisë në shekullin e 13."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Apostull Onesimi"},{"t":"p","x":"Ishte nga Frigjia, skllav i Filemonit, i krishterë i zjarrtë nga Koloseti, i njohur për besimin e fortë dhe dashurinë e tij të përsosur. Meqë kishte bërë një vjedhje tek zotëria i tij, Onesimi u arratis dhe u strehua në Romë, atje takoi shën Pavlin, atëherë i burgosur për Krishtin. I prekur nga fjala e korifeut, Onesimi njohu gabimin e tij, u bë i krishterë, u pagëzua dhe nuk vonoi të ecte në udhën e virtyteve. Por shën Pavli, duke mos dashur ta trishtonte Filemonin, i dërgon të arratisurin me një letër ku i kërkon ta falë dhe ta lirojë. Është Letra drejtuar Filemonit. Ai e priti me gëzim letrën e apostull Pavlit dhe e priti Onesimin jo më si skllav, por si një vëlla, dhe e dërgoi të lirë përsëri tek shën Pavli, që ta ndihmonte në misionin e tij. Pas martirizimit të apostullit, Onesimi predikoi me zell doktrinën e shpëtimit. I ndalua dhe u çua para Tertulianit, guvernatorit të Romës, i cili e urrente veçanërisht Onesimin, sepse kishte kthyer në besën e vërtetë gruan e vëllait të tij. Kur Tertuliani e pyeti se përse e kishte braktisur zotërinë e tij, apostulli iu përgjigj: “Tani jam shërbëtor i Zotërisë së vërtetë, Jisu Krishtit!”"},{"t":"p","x":"Guvernatori e pyeti përsëri: “Dhe kush pagoi që ti të lirohesh?” Onesimi iu përgjigj: “Krishti, Biri i Perëndisë së gjallë, që më bleu me çmimin e gjakut të tij”. Si i përbuzi idhujt, Onesimi u dha në tortura. Nuk ndiente asgjë. Pas 18 ditë burgosje dhe tortura, tirani e dëboi në Puzol, pranë Napolit. Me gjithë ndalimin nga autoritetet, Onesimi vazhdoi të predikonte Ungjillin. Kur Tertuliani i mësoi këto, e thirri në Romë. Shenjti refuzoi të ofronte para idhujve. E rrahën për një kohë të gjatë. Ia shkulën mishrat. Sa më shumë i rridhte gjaku, aq më shumë merrte fuqi në shpresë për të mirat e përjetshme. Përfundimisht, tirani, kur pa se nuk po thyhej shenjti, urdhëroi t’ia prisnin gjymtyrët duke e goditur me shkopinj. Nga goditjet ai dha frymën e fundit dhe trupi tij u mor nga një grua e perëndishme e qytetit."},{"t":"p","x":"1. Nderohet në 22 nëntor me shën Filemonin, Arkipin dhe Afian dhe në 4 janar për mbledhjen e 70 apostujve."}]},{"d":16,"m":2,"blocks":[{"t":"intro","x":"Më 16 të këtij muaji, nderojmë kujtimin e dëshmorëve Pamfili, Juliano, Theodhuli, Ilia, Jeremia, Isaia, Samueli, Daniel, të cilët u martirizuan në Qesari të Palestinës në vitin 290."},{"t":"li","x":"Kujtimin e shën Maruthait, episkop në Tagrita të Mesopotamisë në shekullin e 4-5-t, i cili themeloi në Persi një qytet, në të cilin u vendosën lipsanet e dëshmorëve nga Persia."},{"t":"li","x":"Kujtimin e dëshmorëve nga Persia, lipsanet e të cilëve u vendosën në një qytet ngritur enkas për ta nga shën Maruthai."},{"t":"li","x":"Kujtimin e dëshmorit Flavian, patriark i Konstandinopojës (446-449), i cili mori pjesë në Sinodin e Tretë Ekumenik (431); e mbytën me omoforin e tij në Efes në vitin 449."},{"t":"li","x":"Kujtimin e shën Flavian eremitit."},{"t":"li","x":"Kujtimin e shën Marisë së re në Bizia të Thrakës."},{"t":"li","x":"Kujtimin e murgut oshënar Romani."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Martirët e shenjtë Pamfili dhe shokët e tij: Valensi, Juliani, Theodhuli, dhe pesë egjiptianë Elia, Jeremia, Isaia, Samueli dhe"},{"t":"h","x":"Danieli"},{"t":"p","x":"Pamfili vinte nga Bejruti, në Siri. Ishte nxënës i Pieriusit, pasues i Origjenit në krye të shkollës katekitike në Aleksandri, dhe u bë një nga administratorët më të zjarrtë dhe predikues i mësimit të këtij mësuesi të madh. E kishte shpërndarë tërë pasurinë e tij tek të varfrit, që t’i jepej krejtësisht fitimit të virtyteve dhe meditimit të fjalës së Perëndisë."},{"t":"p","x":"Nga Aleksandria shkoi në Qesari të Palestinës, ku pasi u dorëzua prift, u bë drejtor i shkollës teologjike të themeluar nga Origjeni. Madje para persekutimit, jetonte si një martir duke u bërë i vdekur për kënaqësitë e mishit përmes asketizmit dhe i ishte kushtuar me zell të palodhshëm kopimit dhe interpretimit të Shkrimit të Shenjtë, duke përdorur metodën alegorike të mësuesit të tij."},{"t":"p","x":"Më 307, gjatë persekutimit të Maksimin-Dajës, ai u ndalua dhe u çua para qeveritarit mizor të Palestinës, Urbanit, i cili si e vuri në provë për njohuritë filozofike, dha urdhër që t’u sakrifikonte idhujve. Prifti i shenjtë duroi tortura me qëndrueshmëri si të ishte i paturp. E futën në burg, së bashku me dhjak Valensin, plak me pamje fisnike, i cili thoshte përmendësh pasazhe të gjata nga Shkrimi, dhe me plakun Pavël. Për dy vjet qëndruan në burg, deri ditën kur pesë të krishterë nga Egjipti, të cilët kishin shoqëruar rrëfyes të Krishtit të internuar në minierat e Kilikisë, dolën në portat e qytetit në kthimin e tyre drejt atdheut. Kur rojet i pyetën nga vinin, ata nuk fshehën asgjë, por e shpallën veten të krishterë. I arrestuan si keqbërës dhe i çuan para guvernatorit të Qesarisë, Firmilianit. I detyruan të thoshin emrat paganë, por ata thanë emra nga Dhiata e Vjetër: Elia, Jeremia, Isaia, Samuel dhe Daniel. Kur u kërkuan se cili ishte atdheu i tyre, njëri prej tyre u përgjigj: “Jerusalemi” duke nënkuptuar kështu Jerusalemin e ri, Qytetin e Perëndisë së Gjallë, atdheun e gjithë të krishterëve. Gjykatësi dha urdhër t’i rrihnin, por kur pa qëndrueshmërinë e tyre, vendosi t’ua prisnin kokat. Nga tërbimi, nxori Pamfilin dhe shokët e tij dhe i dënoi me të njëjtin dënim. Në kohën që po i çonin për t’i ekzekutuar, Porfiri, një shërbëtor i ri 18 vjet dhe bir shpirtëror i Pamfilit, doli nga turma dhe kërkoi me zë të lartë trupat e martirëve për t’i varrosur. Gjykatësi, më i egër se një bishë e tërbuar, e kapi Porfirin dhe ua dha xhelatëve, të cilët ia çorën mishin deri në të përbrendshmet e tij."},{"t":"p","x":"I torturuar në atë pikë sa nuk nxirrte dot zë, pothuajse pa jetë, Porfirin e dënuan me djegie. Eci drejt vdekjes porsi një atlet fitimtar, me fytyrë të ndriçuar dhe me sytë e drejtuar drejt qiellit."},{"t":"p","x":"Selefki, një nga rrëfyesit që kishte refuzuar të shërbente në ushtri, shkoi dhe ia dha lajmin e martirizimit Pamfilit. Edhe atë e nxorën përpara qeveritarit, i cili pa vonuar e dënoi me vdekje. Disa çaste më vonë, Theodhuli, një plak i perëndishëm dhe i nderuar, i cili ishte i ngarkuar me përgjegjësi nga guvernatori, mbrojti besimin dhe martirët. Atë e dënuan me vdekje të ngjashme si atë të Shpëtimtarit, me kryqëzim. Juliani, një burrë i hyjshëm nga Kapadhokia, pas një udhëtimi, kthehet dhe shkon të nderojë trupat e martirëve. Edhe ky u ndalua dhe e dënuan me zjarr."},{"t":"p","x":"Pas ekzekutimit të Pamfilit, kryetarit të kësaj kohorte të lavdishme, qeveritari i pamëshirshëm urdhëroi që trupat e tyre t’u jepeshin kafshëve mishngrënëse. Por asnjë nga egërsirat nuk iu afruan trupave të shenjtë dhe të krishterët mundën t’i varrosnin denjësisht.1 1 Kemi ndjekur me besnikëri tregimin e nxënësit të Pamfilit, Eusebit të Qesarisë: Martirët e Palestinës XI (SC 55, 153-167)."}]},{"d":17,"m":2,"blocks":[{"t":"intro","x":"Më 17 të këtij muaji nderojmë kujtimin e dëshmorit të madh Theodhor Tironi nga Efhaita e Azisë së Vogël në vitet 307-313."},{"t":"li","x":"Kujtimin e shën Mariamnit, motra e apostull Filipit."},{"t":"li","x":"Kujtimin e shën Afksivit, episkop në Soli të Qipros, nxënës i apostull Markut."},{"t":"li","x":"Kujtimin e mbretërve të Konstandinopojës Markianit (450-457) dhe gruas së tij Pulkeria, të cilët organizuan Sinodin e Katërt Ekumenik (451) në Kalqedhoni të Thrakës."},{"t":"li","x":"Kujtimin e gjetjes së lipsaneve të shën Mina Kalikeladhit në kohën e mbretit Markian, shek. 7."},{"t":"li","x":"Kujtimin e oshënarit Theosterikti."},{"t":"li","x":"Kujtimin e oshënarit Theodhori i heshturi nga Lavra e Kievit, shekulli i 13."},{"t":"li","x":"Kujtimin e shën Ermogjenit, mitropolit në Kazan të Rusisë (1589-1606) dhe më pas patriark i gjithë Rusisë (1606-1612)."},{"t":"li","x":"Kujtimin e oshënarëve Theodhori dhe i nxënësit të tij Romani nga Bullgaria."},{"t":"li","x":"Kujtimin e dëshmorit të ri Theodhori nga Bizanti, piktor, i cili u martirizua në qytetin e Mitilinit në ishullin Lesvos të Greqisë në 1795."},{"t":"li","x":"Kujtimin e shën Mikaelit të Mavroidhit në Adrianopol."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Martiri i madh e i shenjtë Theodhor Tironi * Theodhori, martiri i Krishtit, ishte nga Amasia, në Pont, dhe shërbente në ushtrinë romake në kohën e persekutimit të Maksimianit (rreth 330). I krishterë që në fëmijëri, e mbante besimin të fshehtë, jo nga frika, por sepse ende nuk kishte marrë nga Perëndia shenjën për t’u blatuar si martir. Kur ushtria e tij ishte strehuar pranë qytetit të Efkditës (Elenopont), ai mësoi se banorët e krahinës ishin të terrorizuar nga një dragua i tmerrshëm, i cili fshihej në pyll. Kuptoi se atje ishte prova nëpërmjet së cilës Perëndia do t’i tregonte momentin kur duhej të ofrohej si martir, prandaj shkoi atje dhe kërkoi në pyll. Shkoi deri në fshatin e braktisur nga banorët dhe ku qëndronte një princeshë e krishterë, e rangut perandorak, Eusebia."},{"t":"p","x":"Shenjti u armatos me shenjën e kryqit, shkoi drejt bishës që lëshonte flakë nga goja dhe e mundi me një goditje me heshtë."},{"t":"p","x":"I bindur tani se mund të mundte edhe dragoin shpirtëror, djallin, shën Theodhori shkoi në fushë pa druajtur ta zbulonte veten si të krishterë. Komandanti i trupës urdhëroi që t’u sakrifikonin idhujve, Theodhori qëndroi në tendën e tij. Erdhën ta kërkonin duke e detyruar të merrte pjesë në aktin idhujtar. Por ai u përgjigj: “Jam i krishterë, vetëm Krishtin adhuroj. Ai është Mbreti të cilit i shërbej, dhe vetëm atij i ofroj blatë!” Pyetën edhe të tjerë, por Theodhori i inkurajoi të ishin të denjë deri në fund për Krishtin."},{"t":"p","x":"Natën shkoi në tempullin pagan dhe shkatërroi me zjarr tempullin e perëndeshës Rea, nënën e perëndive duke shkaktuar një trazirë në qytetin e Efkaidës. Një nga shërbëtorët e tempullit e kapi shenjtin dhe e çoi para qeveritarit Puplius. Ai iu përgjigj me qetësi të tij duke thënë se ishte absurde të konsiderosh perëndi një copë dru, pa shpirt. E kërcënuan me tortura të dhunshme, por nuk e frikësuan. E futën në qeli dhe e lanë pa bukë. Natën iu shfaq Krishti për ta ngushëlluar."},{"t":"p","x":"Kështu, Theodhori e kaloi kohën atje me himne, i shoqëruar nga engjëjt."},{"t":"p","x":"E morën dhe e varën me kokë poshtë, por kur panë rezistencën e shenjtit, vendosën ta digjnin të gjallë. Flakët nuk e prekën, por formuan një hark rreth tij, teksa shenjti po jepte frymën e fundit tek Perëndia. Eusebia e perëndishme arriti ta blejë trupin e tij dhe e transportoi në Efkaida, ku edhe u ndërtua një kishë e madhe për nder të Theodhorit."},{"t":"p","x":"Më 361, Julian Apostati, i cili përpiqej me çdo mjet t’i restauronte ritet pagane, kishte vënë re se të krishterët e kishin zakon ta shenjtëronin javën e parë të Kreshmës së Madhe me lutje dhe agjërim. Mizori dha urdhër në prefekturën e Konstandinopojës të spërkateshin gjithë prodhimet me gjakun e flijimeve të idhujve, që asnjë i krishterë të mos i shpëtonte ndotjes së idhujtarisë. Por Zoti nuk e braktisi popullin e tij të zgjedhur. Dërgoi shërbëtorin e tij Theodhor, i cili iu shfaq në vegim patriarkut Eudhoks (360-364) që të zbulohej kurthi i tiranit dhe porositi të krishterët që të mos blinin asgjë nga prodhimet e tregut, por ata do të përgatisnin grurë për t’u ushqyer. Falë ndërmjetimit të martirit të shenjtë Theodhor, populli i krishterë u mbrojt nga idhujt."},{"t":"p","x":"Që atëherë, Kisha e kremton çdo vit këtë mrekulli javën e parë të Kreshmës së Madhe, që t’u mësojë besnikëve se kreshma dhe vetëpërmbajtja kanë pushtet të pastrojnë çdo ndotje të mëkatit."},{"t":"p","x":"Shën Theodhor Tironi kryen edhe shumë mrekulli të tjera për ata që e kërkojnë me besë."},{"t":"p","x":"Një ditë ai u shfaq tërë shkëlqim mbi kalin e tij të bardhë duke i sjellë një vejushe birin e saj të vetëm të zënë rob nga sarrazinët. Ai çliron edhe ata që janë në furtunë, ai zbulon hajdutët, i ndihmon zotërinjtë të gjejnë shërbëtorët e tyre."}]},{"d":18,"m":2,"blocks":[{"t":"intro","x":"Më 18 të këtij muaji, nderojmë kujtimin e shën Leonit I, papë i Romës (440-461)."},{"t":"li","x":"Kujtimin e dëshmorëve Parigori dhe Leoni nga Patara e Azisë së Vogël."},{"t":"li","x":"Kujtimin e dëshmorit Piuli, i cili mbaroi me shpatë."},{"t":"li","x":"Kujtimin e shën Agapitit, episkop i Sinaut nga Frigjia bashkë me Agripën, Viktorinin, Dhorotheun dhe Theodhulin nga Kapadhokia, të cilët u martirizuan në shekullin e 4-t."},{"t":"li","x":"Kujtimin e atit tonë Thomai I, patriarku i Konstandinopojës."},{"t":"li","x":"Kujtimin e oshënarit Kozma, murg i Jakromskit në shekullin e 15."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Ati i shenjtë Leoni i I, Papë i Romës"},{"t":"p","x":"U lind në Romë në një familje fisnike nga Toskana. Nuk vonoi shumë dhe u bë kryedhjakon i Kishës së Romës, përgjegjësi që kishte të bënte me çështje fetare dhe kundërshtime doktrinale të asaj kohe. Gjatë një misioni të tij në Francë, mësoi se papa Çelestini vdiq dhe se pas tij unanimisht populli e kishte zgjedhur atë si pasues."},{"t":"p","x":"E rëndë ishte detyra e tij, sepse perandoria kërcënohej nga barbarët, ishte e minuar nga prishja e riteve, Kishat ishin të përçara nga herezitë duke e lënë popullin e Perëndisë në injorancë dhe indiferencë. Shën Leoni filloi të ripërtërinte klerin dhe të vendoste rregulloren e mirë në Kishat e Afrikës dhe të Siçilisë, të cilat po bëheshin viktima të invazioneve vandale. Në Kishën e Ilirisë, e cila varej atëherë nga Roma, konsolidoi autoritetin e mitropolitit të Selanikut dhe restauroi respektin e hierarkisë kishtare në Kishën e galëve (Franca sot). Me mendjemprehtësi zbuloi makinacionet e heretikëve dhe u dha episkopëve dhe priftërinjve shembullin e bariut të mirë që e jep jetën e vet përmes jetës së tij të paqortueshme, përmes kujdesit që tregonte për organizimin e adhurimit dhe përmes fjalimeve të tij plot oratori. Përveç veprës së tij pastorale, ai meriton lavdërimin e Kishës në fushën dogmatike. Me anë të një sinodi me episkopë të Perëndimit, anuloi vendimet e një pseudo-sinodi të mbledhur nga heretikë në Efes. Madje para pseudo-sinodit të Efesit, shën Leoni i drejton këto fjalë patriarku shën Flavian në një letër:"},{"t":"p","x":"“Të dy natyrat (hyjnore dhe njerëzore) mbeten pra të plota, por mblidhen në një Person të vetëm, madhështia është lidhur me përulësinë, fuqia me dobësinë, përjetësia me të vdekshmen që të lante borxhin, natyra e papranueshme për vuajtjen është bashkuar me atë që mund të vuajë, dhe ashtu siç duhej që ne të shpëtonim, Jisu Krishti u bë njeri, i vetmi Ndërmjetës mes Perëndisë dhe njerëzve, vdiq nga natyra e tij njerëzore duke mbetur i pavdekshëm në natyrën e tij hyjnore (...). Mori trajtën e shërbëtorit pa njollë mëkati, duke e lartësuar natyrën njerëzore pa e pakësuar atë hyjnore; pasi kjo zbrazje, përmes së cilës e padukshmja u bë e dukshme dhe që Zoti i çdo gjëje deshi të bëhej një nga të vdekshmit, ka qenë një bashkëzbritje e mëshirës së tij dhe jo një pakësim i fuqisë së tij (...). Biri i Perëndisë erdhi në këtë botë, duke zbritur nga qëndrimi qiellor, por pa e braktisur lavdinë e Atit të tij; u lind në një rang të ri gjërash dhe me një lindje të re (...). I njëjti Person është në të njëjtën kohë Perëndi i vërtetë dhe njeri i vërtetë, dhe ky unitet është shumë i vërtetë, pasi gjejmë ndërkohë njerishmërinë e njeriut dhe madhështinë e Perëndisë (...). Kisha jeton dhe vazhdon nga ky besim se në Krishti Jisu, njerishmëria nuk është pa hyjninë e vërtetë, as edhe hyjnia pa njerishmërinë e vërtetë”."},{"t":"p","x":"Tregohet se shën Leoni e shkroi këtë letër i frymëzuar nga Fryma e Shenjtë, pasi kish kaluar shumë ditë në kreshmë, lutje e agripni, dhe pasi e shkroi, e vendosi atë mbi varrin e apostull Petros duke iu lutur korifeut ta korrigjonte nga çdo gabim. Pas 40 ditëve, apostulli i shenjtë iu shfaq kur lutej dhe i tha: “E lexova dhe e korrigjova”. Dhe vërtet, kur e hapi letrën gjeti korrigjime nga dora e apostull Petros. Kjo letër u dërgua me disa përfaqësues në sinodin e Efesit, por heretikët nuk e pranuan. Por kur perandori i perëndishëm Marsiani dhe shën Pulkeria e thirrën Sinodin Ekumenik të Kalqedonisë (451) e lexuan solemnisht para të gjithë etërve, të cilët thirrën me një zë: “Kjo është besa e apostujve, besa e Etërve. Petroja foli nëpërmjet gojës së Leonit”."},{"t":"p","x":"Ndërkohë që Lindja vuante nga këto ngjarje, Perëndimi vuante nga sulmet e Atilës dhe hordhive të Hunve, të cilët pasi kishin shkatërruar Gjermaninë dhe Francën, po kërcënonin Milanon dhe Romën. Perandori, senati dhe populli e lutën papën që të ndërmerrte një përpjekje për paqen me tiranin barbar. I veshur me stolitë pontifikale, në krye të një kortezhi priftërinjsh dhe dhjakonësh duke kënduar kantikë, hierarku i shenjtë u paraqit përpara Atilës. Për çudinë e të gjithëve, ai u zbut, dhe madje kur e pyetën sesi ndodhi kjo ai u përgjigj: “Pashë në krah të hierarkut apostull Petron, që mbante një shpatë në dorë dhe më frikësonte me një pamje të tmerrshme”. Kështu Roma shpëtoi për mrekulli, por për pak kohë, sepse populli mosmirënjohës e harroi shpejt mirëbërjen e Perëndisë dhe u kthye në çrregullimet e tij të zakonshme. Kështu Zoti lejoi që qyteti të grabitej nga vandalët e mbërritur nga Afrika. Papa përsëri ndërhyri me paqe që të mos e masakronin popullin dhe të mos i digjnin ndërtesat, megjithatë ata morën një pjesë të konsiderueshme të popullsisë. Papa Leoni ngushëlloi dhe forcoi të mbijetuarit dhe i inkurajoi të ndërtonin kisha. Gjithashtu duhej të dërgoheshin priftërinj dhe lëmoshë për të grabiturit në Afrikë."},{"t":"p","x":"Pjesa tjetër e jetës së shenjtit iu kushtua veprës pastorale, duke korrigjuar abuzimet në disiplinën kishtare, në mbajtjen e autoritetit të Besës së Kalqedonisë, që kërcënohej nga heretikët monofizitë, në veçanti Kishën e Aleksandrisë. Dha shpirtin e tij tek Zoti më 461, pas një shërbimi në fronin pontifikal prej 21 vjetësh."},{"t":"h","x":"Perandoresha Pulkeria"},{"t":"p","x":"Lindi në vitin 399 dhe ishte bija e perandorit Arkadh (395-408) dhe motra e shën Theodhosit. Ajo u martua me plakun Markian. Perandoresha Pulkeria në vitin 439 thirri Sinodin e Tretë Ekumenik në Efes."},{"t":"p","x":"Vite më vonë ajo do të vizitonte qytetin e Antipatreas (Beratin) në Iliri, të cilit do t’i vinte emrin e saj Pulkeriopolis. Gjithashtu perandoresha Pulkeria ndërtoi edhe manastirin e Shën Mërisë së Vllahernës."}]},{"d":19,"m":2,"blocks":[{"t":"intro","x":"Më 19 të këtij muaji, nderojmë kujtimin e apostull Arkipit, nxënës i apostull Pavlit."},{"t":"li","x":"Kujtimin e dëshmorëve Maksimi, Theodhoti, Isiki, Asklipiodhoti dëshmore grua nga qyteti Markianupoli i Thrakës; u martirizuan ndërmjet viteve 285-305."},{"t":"li","x":"Kujtimin e oshënarëve Evgjeni dhe Makari nga Mavritania e Afrikës, shek. 4-t."},{"t":"li","x":"Kujtimin e shënarit Ravula, themelues i manastirit të tij në Konstandinopojë në shekullin e 6."},{"t":"li","x":"Kujtimin e shën Evgjenit dhe Makarit pohues."},{"t":"li","x":"Kujtimin e oshënarit Konon, i cili pagëzoi shumë katikumenë në lumin Jordan në shekullin e 6."},{"t":"li","x":"Kujtimin e oshënares dhe dëshmores Filothei nga Athina e Greqisë (1522-1589)."},{"t":"li","x":"Kujtimin e hierodëshmorit të ri Nikita athoniti, i cili u martirizua nga shumë tortura në qytetin Seres të Greqisë në vitin 1809."},{"t":"li","x":"Kujtimin e shën Mesrob përkthyesit."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Filothei athinase"},{"t":"p","x":"“Zonja e Athinës”. Filizi i lutjeve të pasanikëve pa fëmijë Angjeli dhe Siriga Venizelu. Lindi në Athinë, në vitin 1522 dhe mori një kulturë të pazakontë. Në moshën 14 - vjeçare, e detyruar nga të afërmit, u martua dhe pas tre vjetësh mbeti e ve."},{"t":"p","x":"Pasi i vdiqën dhe prindërit, tashmë e çliruar nga detyrimet familjare, ktheu në manastir një kishë të vogël të shën Andreas aty afër, duke e dhuruar të gjithë pasurinë e saj (rreth vitit 1550). Në dorëzimin murgeshë ndërroi emrin nga Regula në Filothei dhe u bë igumene, duke pasur në fillim si të bindura shërbëtoret e saj dhe më pas shumë të reja intelektuale të Athinës."},{"t":"p","x":"Me investimet e saj dhe kontributin e besimtarëve ndërtoi një punishte, organizoi shkolla, ngriti spitale, strukturoi bujtina pa pagesë dhe institucione të tjera filantropike, sa brenda në manastir, po aq dhe në anekset e tij dhe në metoqet (d.m.th. manastire të vogla të varura nga manastiri qendror). Ky institucion i shenjtë u tregua tashmë një qendër bamirësie, rrezatimi shpirtëror dhe ngushëllimi për rajanë."},{"t":"p","x":"Aristokratja murgeshë frymëzoi besimin për Krishtin dhe atdhedashurinë. Mbrojti sidomos athiniotet nga arbitrariteti i pushtuesve barbarë."},{"t":"p","x":"Turqit, të indinjuar nga veprimtaria e saj, e burgosën, sepse fshehu katër gra, të cilat i shtynin për të ndërruar besimin. Me ndërhyrjen e pleqësisë e lirojnë, por më 2 tetor 1588 turqit mësyjnë dhe e arrestojnë gjatë kohës së agripnisë."},{"t":"p","x":"E godasin aq shumë, sa në fund vdes nga plagët, më 19 shkurt 1589. Lipsani i shenjtë i saj ndodhet në kishën katedrale të kryeqytetit grek."},{"t":"p","x":"Në shenjë mirënjohjeje për të, Athina iu ka dhënë tri lagjeve të saj emra që kanë lidhje me shenjtoren (Filothei, Psikiko, Kalogreza)."},{"t":"p","x":"Filothei, greqisht = mikesha e Perëndisë."}]},{"d":20,"m":2,"blocks":[{"t":"intro","x":"Më 20 të këtij muaji, nderojmë kujtimin e atit tonë Leon çudibërësit, episkop në Katania të Siçilisë në vitin 785."},{"t":"li","x":"Kujtimin e dëshmorit Sadoki, episkop në Persi, i cili u martirizua bashkë me 128 të krishterët e tij."},{"t":"li","x":"Kujtimin e dëshmorëve Didimi, Nemesi dhe Potami nga ishulli i Qipros."},{"t":"li","x":"Kujtimin e oshënarit Visarion çudibërësit nga Egjipti në shekullin e 5-të."},{"t":"li","x":"Kujtimin e shën Kindeas, episkop në Pisidi të Azisë së Vogël."},{"t":"li","x":"Kujtimin e atit tonë Agathon, papë i Romës (678-682)."},{"t":"li","x":"Kujtimin e oshënarëve Plotini, fjeti në paqe."},{"t":"li","x":"Kujtimin e oshënarit Agathon çudibërësit nga Lavra e Kievit në Rusi në shekullin e 14."},{"t":"li","x":"Kujtimin e oshënarëve Kornel, igumen në Lavrën e Shpellave të Kievit dhe Vasiani, nxënës i tij në shekullin e 16."},{"t":"li","x":"Kujtimin e 34 martirëve të shenjtë në Manastirin e Valaamos."},{"t":"li","x":"Kujtimin e shën Elefterit, episkop i Turneit."},{"t":"li","x":"Kujtimin e shën Efqerit, episkop i Orleanit."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Leoni i Katanias"},{"t":"p","x":"U lind nga prindër besëmirë dhe aristokratë, afër bregdetit verior të Adriatikut, në Ravenë, qytet me famë për shkak të monumenteve të lashta të krishtera."},{"t":"p","x":"Falë virtytit të tij e hirotonisin episkop të Katanias në bregdetin lindor të Siçilisë. Punoi me të gjitha mënyrat për hir të grigjës së tij, bënte bamirësi dhe mrekulli, luftonte kundër idhujtarëve dhe heretikëve."},{"t":"p","x":"Me materialet e një tempulli idhujsh ndërtoi kishën e shkëlqyer të shën Lukisë (13 dhjetor), e cila ishte martirizuar në Katania."},{"t":"p","x":"Në ishull ushtronte veprimtari njëfarë Hiliodhori, që kishte bërë marrëveshje me djallin që të mohonte Krishtin dhe si shpërblim t’i plotësonte çdo dëshirë. Pra magjistari me magjitë e tij shkaktonte trazira dhe shqetësime, kështu që u dënua me vdekje. Por nuk e kapnin dot pasi u shmangej."},{"t":"p","x":"Më kot hierarku përpiqej që ai të vinte mend. Më në fund Hiliodhori u fut në kishë, këtë gjë e kishte bërë dhe herë të tjera, dhe gjatë shërbesës nisi të kërcejë dhe të bëjë gjëra të pahijshme."},{"t":"p","x":"Episkopit i erdhi në majë të hundës, e lidhi me petrahilin e tij, qortoi shpirtin e papastër, kështu humbi çdo fuqi dhe tërhoqi brenda në zjarr të dënuarin duke u futur edhe ai vetë. Ai që ishte i keq si satani u bë shkrumb, ndërsa ai që ishte i shenjtëruar si engjëll mbeti i paprekur!"},{"t":"p","x":"Ngjarja pati jehonë, saqë perandori Leon VI (886 - 912) dhe biri i tij, Konstandini VII (913 - 959) e thirrën në Konstandinopojë ku e nderuan me shpresëtari. I temjanisi me temjan mbi qymyr të ndezur që e kishte në rason e tij - të tjerë pretendojnë se bëhet fjalë për perandorët Leon IV (775 - 780) dhe birin e tij, Konstandin VI (790 - 797) dhe përcaktojnë fjetjen e tij rreth vitit 785."},{"t":"p","x":"Çuditë vazhduan dhe pas vdekjes së tij. Gjakrrjedhura aristokrate e Sirakuzës, e dëshpëruar nga mjekët (si gjakrrjedhura e Ungjillit [Mark. 5.25-26] ) nga sëmundja e pashërueshme mbërriti kur bëhej varrimi i tij. U hodh mbi të e mbytur në lot dhe menjëherë u shërua. Lipsanin e shenjtë e mbyllën në Kishën e shën Lukisë ku buronte miro shëruese."},{"t":"p","x":"Leon, greqisht = luan."}]},{"d":21,"m":2,"blocks":[{"t":"intro","x":"Më 21 të këtij muaji, nderojmë kujtimin e atit tonë oshënar Timotheu nga Simvoli e Bitinisë, shek. e 9."},{"t":"li","x":"Kujtimin e atit tonë Efstathi, patriark i Antiokisë (324-332), i cili mori pjesë në Sinodin e Parë Ekumenik (325)."},{"t":"li","x":"Kujtimin e atit tonë Joani III Skolasti, patriark ekumenik i Konstandinopojës në vitin 557."},{"t":"li","x":"Kujtimin e atit tonë Zaharia, patriark i Jerusalemit (609-632)."},{"t":"li","x":"Kujtimin e atit tonë Gjergji, episkop në qytetin Amastridë në Azinë e Vogël (788-806)."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Gjergji i Amastridës"},{"t":"p","x":"Qe bir prej prindërve të pasur dhe shpresëtarë, Theodhosit dhe Megethosë. U lind rreth vitit 760, jashtë qytetit të Amastridhës, që ndodhej në brigjet perëndimore të Azisë së Vogël në Detin e Zi."},{"t":"p","x":"Prindërit e tij, të moshuar dhe pa fëmijë, kreshmonin dhe luteshin për t’u bërë me fëmijë, derisa dëgjuan një zë hyjnor që u njoftonte shtatzëninë, emrin dhe funksionin arkihieratik."},{"t":"p","x":"Pasi u edukua, ai i braktisi dhe në malin Siriki aty afër u bë murg prej jerontit të tij që qe eremit dhe jetonte në shpellë. Pas vdekjes së këtij, Gjergji hyri në një manastir."},{"t":"p","x":"Ushtrimi i tij i dha famë, sa që kur vdiq kryeprifti i Amastridhës (787) u zgjodh prej besimtarëve si kryebariu i tyre. Ky nuk e pranoi fare, kështu që e çuan me dhunë në Konstandinopojë!"},{"t":"p","x":"Patriku, shën Tarasi (25 shkurt) e miratoi zgjedhjen, por perandori, Konstandini VI (780-794) kishte kandidat tjetër. Mosmarrëveshjen e zgjidhi sinodi, i cili i shqyrtoi që të dy dhe njëzëri zgjodhi oshënarin. U dorëzua aty, me sa duket në vitin 788."},{"t":"p","x":"Orthodhoks dhe mëshirues, mbrojtës i të varfërve, kujdestar i klerikëve, mendohej sa qe gjallë i shenjtë e mrekullibërës. Arriti që episkopata e Amastridës të lartësohet nga Tarasi në mitropoli, ndërsa më parë varej nga mitropolia e Gangrës, gjë që krijonte probleme."},{"t":"p","x":"Fjeti midis viteve 802 dhe 807, ndoshta në vitin 806. Më parë (më 797) Amastrida i bëri qëndresë heroike invazionit të arabëve të Mesopotamisë, të cilët, megjithatë, shkaktuan shumë dëme; në vitin 865 (ose më 941) u plaçkit nga rusët, të cilët deshën të grabisnin dhe varrin e shenjtit në kishën e qytetit, por ata u ndaluan nga një forcë padukshme. Atëherë ata besuan dhe u shpërndanë."},{"t":"p","x":"Gjergji na paraqitet gjithashtu edhe si himnshkrues troparesh. Kremtohet dhe më 25 tetor dhe disa herë edhe më 8 shkurt, që është dita e fjetjes së tij."}]},{"d":22,"m":2,"blocks":[{"t":"intro","x":"Më 22 të këtij muaji, nderojmë gjetjen e lipsaneve të dëshmorëve Androniku dhe gruaja e tij Junia në Evgjeni, në kohën kur patriark në Konstandinopojë ishte Thomai I (607-610)."},{"t":"li","x":"Kujtimin e shën Papias, episkop i Ierapolit."},{"t":"li","x":"Kujtimin e oshënarit dhe pohuesit Athanasi nga Pavlopetri i Nikomedisë në Azinë e Vogël në shekullin e 9."},{"t":"li","x":"Kujtimin e atit tonë Telesfori, papë i Romës (125-136)."},{"t":"li","x":"Kujtimin e hierodëshmorit Aristion, episkop pas apostull Varnavës në Qipro."},{"t":"li","x":"Kujtimin e dëshmoreve Anthuza bashkë me 12 shërbëtoret e saj, të cilat mbaruan me shpatë."},{"t":"li","x":"Kujtimin e dëshmorit Sineti, mbaroi me shpatë."},{"t":"li","x":"Kujtimin e oshënarëve Thalasi dhe nxënësit e tij Limneu dhe Varadhati nga Siria në shekullin e 5-të."},{"t":"li","x":"Kujtimi e shën Vlashit, episkop, fjeti në paqe"},{"t":"li","x":"Kujtimin e shën Leontit, asket në Liki."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Etërit e nderuar Thalasi dhe Limneu"},{"t":"p","x":"Këta etër të shenjtë jetuan në Siri, në kohën kur ishte episkop Theodhoriti i Kirit, ku ky i fundit përfitoi nga shoqëria e tyre dhe raportoi gjithashtu edhe jetën e tyre. Shën Thalasi themeloi një manastir kinovitik mbi një kodër dhe shkëlqeu nga të gjithë asketët e kohës së tij përmes butësisë dhe gjykimit të tij të ekuilibruar. Limneu kishte hyrë që i ri në manastirin e Thalasit që të mësohej prej tij. Duke e ditur se gjuha është gjithnjë një rast për mëkat, që kur hyri në manastir u ushtrua në një heshtje të plotë. Pasi i kishte stampuar si një vulë mësimet e jerontit të tij të shenjtë, shkoi pranë shën Maronit (14 shkurt)."},{"t":"p","x":"Pas disa vitesh, ndjeu dëshirën për t’u martirizuar çdo ditë në natyrë, ashtu si bashkëdishepulli i tij Jakobi (26 nëntor). Atëherë shkoi në një mal të qytetit Targola dhe qëndroi atje për më shumë se 38 vjet, duke u përballur me çdo vështirësi të kohës, i mbyllur, e hapte derën vetëm për episkopin Theodhorit."},{"t":"p","x":"Përmes një dritareje fliste me vizitorët, nga atje u jepte bekimin, shëronte dhe nxirrte demonë. Kur sëmurej vetë, duronte si Jovi, e qetësonte dhimbjen me thirrjen e Emrit të Jisuit."},{"t":"p","x":"Në këtë mënyrë mbeti i paprekur nga kafshimet e gjarpërinjve. Kishte mëshirë për të verbrit e krahinës, i mori në ndërtesat që kishte ndërtuar përreth kasolles së tij, dhe i nxiti vizitorët t’i shërbenin. Në mes të tyre si një shtyllë lutjeje, njeriu i Perëndisë i nxiste ta shenjtëronin vuajtjen e tyre duke i psalur pa pushim Krijuesit."}]},{"d":23,"m":2,"blocks":[{"t":"intro","x":"Më 23 të këtij muaji, nderojmë kujtimin e hierodëshmorit Polikarpi, episkop i Smirnës në Azinë e Vogël në vitin 168."},{"t":"li","x":"Kujtimin e shën Aleksandrit që nuk fjeti kurrë, fjeti në paqe më 430."},{"t":"li","x":"Kujtimin e dëshmorit Klementi, mbaroi me shpatë."},{"t":"li","x":"Kujtimin e dëshmores Thea, mbaroi me shpatë."},{"t":"li","x":"Kujtimin e shën Gorgonisë, motra e shën Grigor Theologut në vitin 370."},{"t":"li","x":"Kujtimin e oshënarëve Joani, Moisiu, Antonini nga Siria në shekullin e 5të."},{"t":"li","x":"Kujtimin e oshënarëve Zevini bashkë me nxënësit e tij Polikroni, Moisiu dhe Damiani nga Siria, shek. e 5-të."},{"t":"li","x":"Kujtimi e oshënarit Joan Theristi (korrësi) nga Palermo e Italisë në shekullin e 11."},{"t":"li","x":"Kujtimin e oshënarit Damian nga Manastiri Esfigmenu në Malin e Shenjtë në vitin 1280."},{"t":"li","x":"Kujtimi e oshënarit dhe dëshmorit Damian nga Manastiri i Esfigmenut, fjeti në paqe më 1280."},{"t":"li","x":"Kujtimin e shën Llazarit në Peloponez."},{"t":"li","x":"Kujtimin e shën Moisiut, murg në Liqenin e Bardhë (Belozhersk), në Rusi."},{"t":"li","x":"Kujtimin e oshënar Polikarpit, themelues i manastirit me emrin e tij në Brianski të Rusisë në vitin 1449."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Polikarpi i Smirnit"},{"t":"p","x":"Është “Atë Apostolik”. U lind rreth vitit 70 pas Krishtit. Mësoi pranë ungjillor Joanit (26 shtator) dhe ishte pasardhës i episkopit të Smirnit shën Vukolit (6 shkurt). Ishte mbartës i Traditës Apostolike dhe veprimtaria e prestigji i tij e afirmuan atë si “prijës të të gjithë Azisë”."},{"t":"p","x":"Teologjikisht u influencua nga shën Ignat Hyjprurësi (20 dhjetor), të cilin e respektonte së tepërmi, por dhe ky i fundit nga ana e tij e donte pa masë. Polikarpi (greqisht = i shumëfrytshëm) risolli shumë heretikë në grigjën e Krishtit."},{"t":"p","x":"Pas kthimit nga Roma, ku kishte takim (në vitin155) me papën Anikit, lidhur me çështjen e kremtimit të Pashkës edhe pse ishte në periudhën e pleqërisë së bardhë, gjallëria e tij rinore vazhdoi."},{"t":"p","x":"Pikërisht, zelli i tij i shumëfrytshëm irritoi idhujtarët. Sipas një letre të kohës së Kishës së tij, thuhet se në një ndeshje gladiatorësh me bisha të egra, turma idhujtare kërkoi ta hidhnin në arenë Polikarpin."},{"t":"p","x":"Ai u gjet në një arë, ku me vështirësi kishte pranuar të fshihej prej besimtarëve. U kap, edhe pse kishte mundësi të ikte përsëri."},{"t":"p","x":"Me qëndrueshmëri të paqshme, shën Polikarpi dha porosi t’u jepnin për të ngrënë ekzekutorëve, të cilët kishin ardhur për ta marrë dhe kishin shtangur nga figura e tij. Pastaj, pasi e lejuan u lut për dy orë, për Kishën e tërë botës."},{"t":"p","x":"Duke hyrë në arenë dëgjoi një zë hyjnor: “Forcohu, Polikarp, qëndro si burrat”. Disa ditë më parë ai kishte parë në një vegim jastëkun e vet të digjej. “Duhet të digjem së gjalli”, - kishte thënë atëherë."},{"t":"p","x":"Kështu nuk u bëri flijime idhujve por u hodh në zjarr; flakët e mbështollën, por ato u bënë si mburojë për të dhe ajri u aromatizua."},{"t":"p","x":"Sipas Sinaksarit e goditën me shtizë dhe vdiq brenda në zjarr (168). U preferua vdekja e tij me anë të zjarrit, që të mos i mbeteshin eshtrat, se kishin frikë, se të krishterët do të braktisnin dhe vetë të Kryqëzuarin e do adhuronin Polikarpin!"},{"t":"p","x":"Ruhet një letër e tij, me përmbajtje të larmishme, dërguar Filipianëve, e ndryshme nga ajo e Apostull Pavlit në Dhiatën e Re."}]},{"d":24,"m":2,"blocks":[{"t":"intro","x":"Më 24 të këtij muaji, kujtojmë gjetjen e parë dhe të dytë të kokës së shën Joan Pagëzorit, Pararendësit të Zotit tonë Jisu Krisht."},{"t":"li","x":"Kujtimin e oshënarit Erazmi nga Lavra e Kievit të Rusisë në shekullin e 12."},{"t":"li","x":"Kujtimin e gjetjes së lipsanit të shën Romanit, princ i Ugliçit."},{"t":"li","x":"Kujtimin e martirëve të shenjtë Mantani, Luki, Juliani, Viktoriku dhe Flaviani, si dhe shokët e tyre në Kartagjenë."},{"t":"li","x":"Kujtimin e shën Ethelbertit, mbreti i krishterë i Kentit në Angli."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Gjetja e parë dhe e dytë e kryes së të shenjtit, të lavdëruarit Profetit"},{"t":"h","x":"dhe Pararendësit Joan Pagëzorit"},{"t":"p","x":"Shumë kohë më vonë, pas prerjes së kokës1 së Joan Pagëzorit, dy murgj nga Lindja mbërritën në Palestinë për të nderuar Vendet e Shenjta. Shën Joan Pagëzori iu shfaq natën secilit më vete, dhe u tha: “Shkoni në pallatin e Herodit, atje do të gjeni kokën time që prehet nën tokë.” Të udhëhequr nga hiri hyjnor, nuk e patën të vështirë të gjenin vendin ku ishte koka e çmuar; e morën në çantë dhe u kthyen."},{"t":"p","x":"Gjatë rrugës, takuan një poçar nga Emesa, i cili në varfërinë e tij, e kishte braktisur atdheun për një mundësi më të mirë."},{"t":"p","x":"Me anë të një zbulimi gjatë natës, e mori lipsanin e çmuar dhe u kthye në Emesa ku pati një mbarësi të madhe. Në çastin kur do largohej nga kjo jetë, e futi këtë thesar të çmuar në një kuti dhe ia la motrës së tij dhe e urdhëroi të mos e hapë atë pa kërkuar lejen e atij që fshihet brenda, dhe kur edhe ajo do të largohej nga kjo jetë t’ia linte një njeriu të Perëndisë këtë thesar. Në këtë mënyrë, koka e shën Joan Pagëzorit arriti më në fund tek një prift me emrin Eustath, i cili ushtrohej në një shpellë jo larg qytetit të Emesa, por që fshehtazi rrëfente herezinë e Ariosit."},{"t":"p","x":"I pushtuar nga krenaria për shkak të mrekullive që lipsani i Pagëzorit bënte, ai ia dedikonte vetes. Si u zbulua herezia e tij, u dëbua dhe koka e nderuar e shën Joanit deri në kohën e të perëndishmit Markel, njeri i dashur nga Perëndia dhe mik i virtytit. Ai u zgjodh igumen i manastirit të themeluar pranë shpellës, nën mbretërimin e perandorit Markian (450- 457) dhe episkopit të ndritur Uranios, episkop i Emesës."},{"t":"p","x":"Shumë herë shën Joan Pagëzori iu shfaq Markelit duke i dëshmuar simpatinë e tij dhe duke i dhënë një vazo plot me mjaltë. Më pas, i udhëhequr nga një yll që ndaloi mbi një fole të shpellës, Markeli filloi të hapte një gropë, pasi më parë e kishte temjanisur atë. Atëherë zbuloi nën një pllakë mermeri lipsanin e çmuar të fshehur në një kuti, ai e nderoi me lot dhe gëzim. Lipsani u vendos nga episkopi në kishën kryesore të Emesës. Qyteti pati shumë bekime. Më vonë lipsani u transferua në Konstandinoopojë, në shekullin e IX, nën mbretërimin e Mikailit III (842-867) dhe patriarkut Ignat. Ky transferim është edhe origjina e caktimit të festës sot.2 1 Në shekullin e IV, varri i shën Joan Pagëzorit nderohej bashkë me varret e profetëve Elise dhe Abdia në Samari. U shkel nga Julian Apostati (361) dhe kockat e tij u shpërndanë. Por të krishterë të perëndishëm mundën të shpëtonin pjesë prej tij dhe dhe e sollën në Jerusalem, tek igumen Filipi, i cili i vendosi tek shën Athanasi i Aleksandrisë. Pelegrinazhi në Varrin e shenjtit ne Sebasti vazhdoi për shekuj. Sinaksarët sllavë raportojnë një traditë të panjohur nga sinaksarët bizantinë, sipas së cilës një grua që e shoqëronte Herodianën, Joana, gruaja e Kuzës, e cila u bë një nga miroforet, duke mos duruar që koka e Pararendësit të qëndronte në një vend të padenjë, e mori dhe e varrosi fshehur në Jerusalem, në Malin e Ullinjve, ku u gjet më vonë nga një murg."},{"t":"p","x":"2 Kemi përmbledhur këtu versionin e shën Simeon Metafrastit. Sipas disa historianëve të tjerë bizantinë (Sozomentit, Kronikon, Psakalit, PseudoKodinos), koka e Pararendësit u gjet në Palestinë nga dy murgj dhe u transferua nga ata në Cilici. Kur e mësoi këtë, perandori Valens (364-375) i dha urdhër prefektit të Pallatit, Mardonios, ta sillte në Konstandinopojë. Gjatë rrugës, kamioni për mrekulli mbeti në Panteikion (Bitini). U desh të lihej në pronën e Mardonios, Kosilaos, nën mbikëqyrjen e një murgeshe të një herezie të asaj kohe, Matrona, e cila kishte nën varësi një komunitet murgjish. Pas vdekjes së saj, prifti Vikent, i kthyer në besën e vërtetë u kujdes për lipsanin deri ditën kur perandori Theodhosi i Madh e mori me shumë devotshmëri në xhepat e palltos së tij, më 17 shkurt 392, dhe e vendosi në kishën madhështore të lagjes së Ebdomonit, që e kishte ndërtuar posaçërisht për ta vendosur atje."},{"t":"h","x":"Erazmi i drejtë i Lavrës së Kievit"},{"t":"p","x":"Vinte nga një familje tepër e pasur, prej së cilës trashëgoi edhe një thesar të madh. E donte kishën e Zotit, prandaj dhe atë që kishte e dhuroi për zbukurimin e kishave dhe të ikonave."},{"t":"p","x":"Por djalli filloi ta ngacmonte me mendime se përse e dha pasurinë për kishat dhe jo tek të varfrit. I lumuri nuk e kuptoi këtë sulm të të ligut dhe filloi të dëshpërohej, aq sa të shpenzonte kohë edhe me gjëra të kota e madje të turpshme."},{"t":"p","x":"Por Perëndia i tërëmëshirshëm e ruajti Erazmin nga humbja nëpërmjet një sëmundje që i solli. Pra u sëmur rëndë, shkoi deri në buzë të varrit. Gjendja e tij u bë aq keq sa nuk mundi të fliste e të shikonte për shtatë ditë. Ditën e tetë erdhën vëllezërit në qelinë e Erazmit, dhe njëri prej tyre i tha: “Mjerë shpirti i këtij vëllai, se jetoi në dembelizëm dhe në mëkate, dhe tani shpirti i tij sheh në errësirë”."},{"t":"p","x":"Kur Erazmi i dëgjoi këto, tha: “Etër dhe vëllezër! Është e vërtetë, ashtu siç ju thoni, se jam mëkatar dhe nuk kam pendim, por sot etërit tanë të shenjtë Andoni dhe Theodhosi u shfaqën tek unë dhe më thanë: “Iu lutëm Zotit për ty, dhe ai të dha kohë për pendim. Më pas, pashë të Tërëshenjtën, ashtu siç është në ikonë, të mbante në duart birin e saj e rrethuar nga shenjtorët, dhe ajo më tha: “Erazëm, sepse ti ke zbukuruar kishën time, (Katedralen e Fjetjes së Hyjlindëses) prandaj edhe unë do të të ngazëlloj në mbretërinë e Birit tim; të varfrit janë gjithnjë më ju, por kisha nuk ka kudo. Ngrihu tani, pendohu dhe pas tri ditësh do të largohesh nga kjo jetë”."},{"t":"p","x":"Pasi i tha këto, Erazmi u rrëfye para vëllezërve pa turp dhe mori skimën engjëllore, dhe pas tri ditësh shkoi tek Zoti."}]},{"d":25,"m":2,"blocks":[{"t":"intro","x":"Më 25 të këtij muaji, nderojmë kujtimin e atit tonë Tarasi, patriark ekumenik i Konstandinopojës (784-806), i cili ishte kryetar i Sinodit të Shtatë Ekumenik (786-787)."},{"t":"li","x":"Kujtimin e dëshmorit Aleksandër Romani nga Drizipari i Thrakës, që e mbaroi jetën me shpatë në vitin 305."},{"t":"li","x":"Kujtimi e atit tonë hierodëshmor Regjini, episkop në ishullin e Skopelos në Greqi, mbaroi me shpatë në vitin 362."},{"t":"li","x":"Kujtimin e 40 dëshmorëve, të cilët u martirizuan bashkë me shën Rigjinin."},{"t":"li","x":"Kujtimin e shën Pafnutit i Kefalasit."},{"t":"li","x":"Kujtimin e dëshmorit Andoni, të cilin e shtrinë mbi një skarë dhe e dogjën."},{"t":"li","x":"Kujtimin e shën Theodhorit, i marrë për Krishtin, fjeti në paqe."},{"t":"li","x":"Kujtimin e shën Markelit, episkop në Apamia të Sirisë."},{"t":"li","x":"Kujtimin e shën Valburgës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Tarasi i Konstandinopojës"},{"t":"p","x":"Biografinë e tij e shkroi dhjaku i tij, më vonë patriarku i Konstandinopojës shën Ignati (23 tetor). Tarasi ishte xhaxhai i shën Fotit të Madh (6 shkurt). Lindi rreth vitit 730 nga patricët shpresëtarë Gjergji, gjykatës dhe Efkratia. Ai u arsimua dhe mori një kulturë mjaft të gjerë, ndaj u dallua si kryesekretar i mbretërve Konstandin VI (790-797) dhe Irini (780-802)."},{"t":"p","x":"Pa dëshirën e tij, edhe pse nuk ishte klerik, u zgjodh dhe u hirotonis patriark më 25.12.784. Duke qenë mik i ikonave, u përpoq dhe u mblodh Sinodi VII Ekumenik në Nikea (787), që dënoi ikonoklazmën. Tarasi ishte kryetari i Sinodit. Asketik, i përulur, didaktik, i dhembshur, themeloi një spital të famshëm dhe një azil për të varfrit. Herë pas here ai vetë u shërbente të vobektëve."},{"t":"p","x":"Ngriti në Bosfor një manastir privat, “punishte” virtyti. Shfarosi “simoninë” (hirotonisjen me para) – “Pidalioni” (= Timoni) përmban një letër të tij që ka lidhje me çështjen. U kujdes për pajtimin me Kishën Perëndimore. Iu kundërvu mbretërve për hir të një të dënuari padrejtësisht, derisa e shpallën të pafajshëm, por më tepër iu kundërvu për hir të moralit: kur Konstandini e dëboi gruan e vet (796), që të martohej me oborrtaren Theodhota, mbajti qëndrim të rreptë ndaj tij, sa e futën në arrest shtëpie. Reaguan edhe besimtarët, me në krye studitët, shën Platonin (4 prill) dhe shën Theodhorin (11 nëntor), të cilët dhe u ndëshkuan për këtë. E qortuan edhe Tarasin, sepse nuk kishte dënuar celebruesin e kurorëzimit, prift Josifin, por kur ai më vonë e zhveshi, e lavdëruan."},{"t":"p","x":"Pas shfronëzimit të Konstandinit (797) u çlirua dhe baritoi në paqe deri në fund të jetës. Kur po jepte shpirt largoi me turp demonët që e akuzonin me gënjeshtra. Gjatë varrimit të tij mbarëbotëror (25.2.811) perandori Niqifori I (802-811) mbuloi me mantelin e vet mbretëror lipsanin e tij, që u varros në manastirin e tij. Vaji i kandilit të varrit shëronte të demonizuar dhe të sëmurë, si p.sh. gra me hemorragji që, duke u hequr si eunuke u futën fshehurazi në manastirin e tij, ku nuk lejoheshin femrat."},{"t":"p","x":"Në 1018 lipsanin e shenjtë e vodhën venedikasit. Ruhet një Homeli e tij për Hyrjen e Virgjëreshës në Tempull."},{"t":"p","x":"Hieromartiri i shenjtë Regjini, episkopi i Skopelos, mbaron më"},{"t":"h","x":"shpatë"},{"t":"p","x":"U lind në Livadhia të Beotisë në fund të shekullit të III-të nga prindër të krishterë, të cilët frymëzuan tek ai dashurinë për virtytin dhe zellin për të vërtetën."},{"t":"p","x":"Kur episkopi i Skopelos vdiq, shenjti u zgjodh si bari nga i gjithë populli entuziast."},{"t":"p","x":"Kur herezia ariane vazhdonte të tërbohej pas Sinodit të Nikesë (325), u mblodh një tjetër sinod në Sardikë (Sofie, Bullgari), më 343, në të të cilin shën Regjini u dallua për mendjemprehtësinë për dëbimin e heretikëve."},{"t":"p","x":"Kur besimi i vërtetë triumfoi, ai u kthye në dioqezën e tij, por nuk pati paqe, sepse Julian Apostati kishte nxitur një persekutim të ashpër kundër të krishterëve (361) dhe prefekti i Eladhit erdhi një ditë për të kapur episkopin dhe disa nga besnikët e tij. Shenjti inkurajoi besimtarët të qëndronin të patundur në besim. Pasi panë vendosmërinë dhe besimin e tij, magjistrati vendosi t’ia prisnin kokën, 25 shkurt 362. Lipsani i tij u transferua në Qipro dhe vetëm në shekullin e 19 besimtarët e Skopelos mundën të gjenin disa fragmente të tij."}]},{"d":26,"m":2,"blocks":[{"t":"intro","x":"Më 26 të këtij muaji, nderojmë kujtimin e atit tonë Porfiri, episkop i Gazës në Palestinë, në shekullin e 5-të."},{"t":"li","x":"Kujtimin e dëshmores Fotini Samaritane, dhe i motrave të saj: Fota, Fotis, Parashqevia, Kirjakia, djemtë e saj: Viktori (Fotino), Josiu, duka Sebastiani dhe oficeri Anatoli."},{"t":"li","x":"Kujtimin e shën Kristodhulit, mbaroi me shpatë."},{"t":"li","x":"Kujtimin e dëshmorit Theokliti, magjistar, i cili besoi në fund tek Krishti dhe mbaroi me shpatë."},{"t":"li","x":"Kujtimin e oshënarit Nikolla i Katopinit."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Fotinia, Fotini, Josiu, Sevastiani, Anatolia, Fotoa, Fotidha,"},{"t":"h","x":"Parashqevia, Qirjaqia,"},{"t":"h","x":"Martirë"},{"t":"p","x":"Takimin e Fotinisë, gruas samaritane, me Krishtin e përshkruan Ungjilli i Joanit (4.5-42)."},{"t":"p","x":"Sipas sinaksarit, pesë gratë e tjera ishin motra të saj. Që të gjashtë, si dhe dy djemtë e Fotinisë, Fotini (ose Viktor) dhe më i vogli, Josiu, udhëtonin dhe predikonin Krishtin duke patur rezultate tepër të çmuara."},{"t":"p","x":"Fotinia (greqisht = e ndritur si edhe emrat Fotini, Fotoa, dhe Fotidha) dhe Josiu (hebraisht = [Perëndia] shton) vepronin në Kartagjenë të Afrikës së Veriut. Fotini, në sajë të trimërisë së tij ishte bërë prej perandor Neronit (54-68) kryegjeneral dhe ishte urdhëruar për të ndjekur të krishterët."},{"t":"p","x":"Duka idhujtar, Sevastiani (greqisht = i respektuar) e këshilloi që t’i bindej urdhrit. Por ky nuk pranoi, dhe Sevastiani u verbua dhe u bë memec, por u pagëzua dhe në çast u shërua! Rezultati: u ndriçuan edhe të tjerë, gjë që do të përsëritej edhe në të ardhmen."},{"t":"p","x":"Neroni i mori vesh këto dhe dërgoi për ta arrestuar. Atëherë panë Zotin që u jepte zemër dhe marshallin e mbiquajti Viktor (latinisht = fitimtar)."},{"t":"p","x":"Gratë shenjtore dhe Josiu, pas një zbulese të mbina-tyrshme, erdhën në Romë tek Neroni, ndërsa njëkohësisht para tij sillnin Fotinin dhe Sevastianin."},{"t":"p","x":"Ata nuk bënë flijime. Edhe pse xhelatët e tyre herë pas here pësonin ndonjë të keqe, vetë këta me ndihmën e Krishtit mbetën të paprekur nga torturat e njëpasnjëshme për tre vjet: goditje me çekiç të gishtërinjve, hedhje në furrë, pirje e helmit të magjistarit Lambadh (ose Theoklit, i cili më pas besoi e u martirizua dhe e kremtojmë sot), derdhje plumbi të shkrirë ose uthulle në gojë, vesh dhe hundë, shqyerje, djegie me llambadha, verbim, burgosje së bashku me gjarpërinj, kryqëzim kokëposhtë etj. Madje u prenë edhe gjymtyrët. Më parë gratë shenjtore nuk ishin gënjyer nga sendet e florinjta që u ofruan, as nga shoqërimi me vajzën e Neronit, Domnina, të cilën përkundrazi e pagëzuan me emrin Anthusa."},{"t":"p","x":"Së fundi, Fotidha u copëtua kur e lidhën në majat e dy pemëve të përkulura që i lëshuan menjëherë, të tjerëve iu pre koka. Vetëm Fotinia fjeti më vonë në burg (rreth vitit 67), pasi më parë e kishin hedhur për pak kohë në një pus të thatë. Anatolia, Parashqevia dhe Qiriaqia, greqisht = lindja, përgatitja dhe zotëruesja përkatësisht."}]},{"d":27,"m":2,"blocks":[{"t":"intro","x":"Më 27 të këtij muaji, nderojmë kujtimi e atit tonë oshënar dhe pohues, Prokop Dekapolitit në shekullin e 8."},{"t":"li","x":"Kujtimin e dëshmorit Gjelas aktori, i cili u porosit nga kryetari pagan që të përqeshë pagëzimin orthodhoks, por erdhi Shpirti i Shenjtë tek ai, besoi Krishtin dhe pranoi në fund shpatën mbi kokën e tij duke fituar kurorën e martirit."},{"t":"li","x":"Kujtimin e dëshmorit Nisi."},{"t":"li","x":"Kujtimin e oshënarëve Asklepi dhe Jakovi nga Siria në shekullin e 4-t."},{"t":"li","x":"Kujtimin e oshënarit Thaleleu i Sirisë në shekullin e 4-t."},{"t":"li","x":"Kujtimin e oshënarit Stefan, i cili themeloi azilin e pleqve në Konstandinopojë."},{"t":"li","x":"Kujtimin e shën Simeonit të Kirenës, babai i Aleksandrit dhe Rufit, i cili mbajti kryqin Zotit që shkonte në Golgotha."},{"t":"li","x":"Kujtimin e shën Gerontit."},{"t":"li","x":"Kujtimin e oshënarit Timothe nga Qesaria."},{"t":"li","x":"Kujtimin e martirit të ri Ilia i Trivizundës, e varën më 1749."},{"t":"li","x":"Kujtimin e oshënarit Titi, prifti nga Lavra e Kievit të Rusisë në vitin 1190."},{"t":"li","x":"Kujtimin e shën Rafaelit të Bruklinit."},{"t":"li","x":"Kujtimin e shën Leandrit, episkop i Seviljes, fjeti në paqe në vitin 600."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Prokop Dekapoliti"},{"t":"p","x":"Jetoi në kohën e persekutimeve të Leonit të III Izaurianit (717-741) kundër ikonave. Vinte nga Dekapoli dhe u bë murg në Konstandinopojë. Si u pastrua nga pasionet dhe dëshirimet e mishit, i shoqëruar nga dishepulli i tij Vasil (28 shkurt), u nisën që të mundnin heretikët të cilët e mohonin mishërimin e Zotit tonë Jisu."},{"t":"p","x":"Përveç fjalës, ai e konfirmoi besimin e tij të vërtetë nëpërmjet shumë vuajtjesh dhe turbullimesh që i vuajti nga dashuria për të vërtetën. Pas vdekjes së tiranit (741), persekutimi u qetësua dhe shën Prokopi u kthye në manastir dhe fjeti në paqe pas shumë vitesh."},{"t":"h","x":"Titi i drejtë i Lavrës së Kievit"},{"t":"p","x":"Titi ishte prift-murg në Manastirin e Shpellave të Kievit. Kishte një vëlla shpirtëror dhjak, i cili quhej Evagër. Titi kishte një dashuri të pastër, jo të shtirur për dhjakun Evagër, madje harmonia dhe dashuria e tyre u bë burim frymëzimi për vëllezërit e tjerë."},{"t":"p","x":"Por djalli që nuk e duronte dot këtë, futi mes tyre mëri dhe urrejtje. I errësoi që të dy në atë pikë sa nëse njëri afrohej kur temjaniste kishën, tjetri dilte jashtë saj, madje kishte raste që tjetri nuk e temjaniste fare vëllain. Qëndruan në këtë gjendje për një kohë të gjatë, edhe pse ishin në mëri, përsëri merrnin kungatën e shenjtë. Vëllezërit i këshillonin të pajtoheshin, por nuk donin t’ia dinin fare për këtë."},{"t":"p","x":"Një herë, Titi u sëmur dhe arriti në një gjendje kritike. Erdhi në vete dhe filloi t’i kërkojë falje Evagrit me këto fjalë: “Më fal vëlla, për hir të Zotit, më fal që të kam lënduar në mërinë time”. Dhjaku Evagër, jo vetëm që nuk e fali, por filloi ta ngacmonte me fjalë mizore. Vëllezërit kur panë se Titi po vdiste, e shtynë Evagrin të shkonte në qelinë e tij e të pajtoheshin. Dhjaku nuk u përul, madje në pandjeshmërinë e tij tha: “Unë kurrë nuk do të pajtohem me të, as në këtë jetë, dhe as në tjetrën”. Sa tha këto fjalë, ai ra përdhe në tokë. Vëllezërit u mblodhën rreth tij që ta ngrinin, por sytë dhe krahët e tij nuk lëviznin. Ndërsa vëlla Titi u ngrit menjëherë në këmbë. Të gjithë u befasuan kur e panë shërimin e Titit dhe e pyetën: “Si ndodhi kështu vëlla?”"},{"t":"p","x":"Dhe ai u përgjigj: “Kur isha i sëmurë, pashë engjëj të largoheshin prej meje dhe të vajtonin mbi rrënojën e shpirtit tim, ndërsa demonët gëzoheshin me mërinë time. Për këtë arsye ju kërkova të shkonit tek Evagri dhe t’i kërkonit të më falte. Kur e sollët në qelinë time, në çastin kur u largua, unë pashë një njeri që mbante në dorë një shigjetë, me të cilën e qëlloi dhe Evagri ra përdhe. Vëllezërit përgatitën varrimin e Evagrit, i cili edhe sytë, edhe gojën e kishte të hapur."},{"t":"p","x":"Pas kësaj ngjarjeje të tmerrshme, vëllezërit bënë kujdes që të mos mbanin mëri njëri me tjetrin. Më pas, Titi gjeti paqen më Zotin dhe filloi ta luftonte pasionin e mbajtjes mëri. Fjeti në paqe dhe lipsani i tij ruhet në shpella."}]},{"d":28,"m":2,"blocks":[{"t":"intro","x":"Më 28 të këtij muaji, nderojmë kujtimi e atit tonë Vasil Konfesori, nxënës i shën Prokopit në shekullin e 9."},{"t":"li","x":"Kujtimin e atit tonë Proteri, patriark i Aleksandrisë (452-457), i cili u martirizua bashkë me 6 klerikë të tjerë nga heretikët monofizitë në Egjipt në vitin 457."},{"t":"li","x":"Kujtimin e apostujve Nimfas dhe Evuli, bashkëpunëtor i apostull Pavlit nga Laodicea e Palestinës, shekulli i parë."},{"t":"li","x":"Kujtimin e hierodëshmorit Nestor, episkop i Magidos në Pamfili (249- 251)."},{"t":"li","x":"Kujtimin e dëshmorit Abriku, mbaroi me shpatë."},{"t":"li","x":"Kujtimin e oshënareve gra Marana dhe Kira nga Veria e Sirisë në shekullin e 6."},{"t":"li","x":"Kujtimin e shën Varsit, episkop në Damask të Sirisë."},{"t":"li","x":"Kujtimin e dëshmores Kirana, virgjëreshë nga Selaniku i Greqisë, e cila mbaroi nga shumë tortura në vitin 1751."},{"t":"li","x":"Kujtimin e shën Nikollës nga Pskovi, i marrë për Krishtin."},{"t":"li","x":"Kujtimin e shën Arsenit, mitropolit i Rostovit."},{"t":"li","x":"Kujtimin e shën Sios (Simeoni), murg në Gjeorgji."},{"t":"li","x":"Kujtimin e shën Romanit dhe Lupikinit, themelues të Manastirit të Kondatit në malet e Jurës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Kirana, që e mbaroi martirizimin e saj në tortura, më 1751 * Vinte nga një qytet afër Selanikut. Bënte një jetë të pastër e të perëndishme."},{"t":"p","x":"Një ditë një jeniçer i cili mblidhte taksat, u pushtua nga një dëshirë satanike për vajzën dhe filloi ta kërcënonte. Pa se vajza qëndronte e palëkundur, ndaj e nxori me forcë para gjykatësit të Selanikut duke nxjerrë edhe disa ushtarë si dëshmitarë të rremë, ai pretendonte se vajza kishte pranuar propozimin e tij për martesë dhe se do të pranonte Islamin. Për të gjitha këto akuzime, shërbëtorja vigjilente e Krishtit tha: “Unë jam e krishterë dhe dhëndri im është Krishti, të cilit i dhuroj edhe virgjërinë time. Atë dua dhe jam gati të derdh gjakun tim për të! Kjo është përgjigjja ime, mos prisni asgjë tjetër nga unë”."},{"t":"p","x":"E futën në burg. Jeniçeri mori lejen të hyjë në burg me disa shokët e tij të cilët e kërcënuan me vdekje nëse nuk pranonte propozimet e tyre. Shenjtorja nuk denjonte t’i hidhte sytë mbi ta, atëherë ata filluan me tërbim ta godisnin: e rrahën me shkop, me grushte e me shkelma. Më pas erdhi roja dhe e varën nga sqetullat dhe filluan ta rrihnin me shkop. I refuzonte ushqimet që i jepnin. Ditën e shtatë, roja i burgut nuk i lejoi jeniçerët të hynin në burg. E denoncuan para magjistratit. Para se të largohej, ai (roja) derdhi tërë urrejtjen dhe zemërimin e tij para shenjtores dhe e la të varur dhe të përgjakur."},{"t":"p","x":"Papritur pa një dritë hyjnore të ndriçonte trupin e saj dhe tërë qelinë, ndërsa shpirti ngjitej tek Dhëndri qiellor, dhe duke lënë pas një erë të mirë. I trembur, roja shpërtheu në vajtim dhe u pendua, madje caktoi një të krishterë të zbriste trupin e shenjtores e ta përgatisnin për varrim. Kur lajmi i kësaj mrekullie u përhap në qytet, të nesërmen, turqit plot turp, ua dhanë trupin të krishterëve që ta varrosnin jashtë qytetit."}]},{"d":29,"m":2,"blocks":[{"t":"intro","x":"Më 29 të këtij muaji, nderojmë kujtimin e shën Joan Kasianit dhe shën Gjermanit."},{"t":"li","x":"Kujtimin e shën Gjergjit, episkop i Develtos."},{"t":"li","x":"Kujtimin e shën Kasianit, nga Lavra e Shpellave të Kievit."},{"t":"p","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"M A R S"}]}]};
